(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0030.js"] = [{"id":"poem-c3ea6718b664b8e33f3c38ec","title":"诫儿姪八百字","author":"范质","dynasty":"宋","verses":["去年初释褐，一命列蓬丘。","青袍春草色，白纻弃如仇。","适会龙飞庆，王泽天下流。","尔得六品阶，无乃太为优。","凡登进士第，四选升校雠。","历官十五考，叙阶与尔俦。","如何志未满，意欲凌云游。","若言品位卑，寄书来我求。","省之再三叹，不觉泪盈眸。","吾家本寒素，门地寡公侯。","先子有令德，乐道尚优游。","生逢世多僻，委顺信沈浮。","仕宦不喜达，吏隠同庄周。","积善有余庆，清白为贻谋。","伊余奉家训，孜孜务进修。","夙夜事勤肃，言行思悔尤。","出门择交友，防慎畏薰莸。","省躬常惧玷，恐掇庭闱羞。","童年志于学，不惰为箕裘。","二十中甲科，赪尾化为虬。","三十入翰苑，步武向瀛洲。","四十登宰辅，貂冠侍冕旒。","备位行一纪，将何助帝猷。","即非救旱雨，岂是济川舟。","天子未遐弃，日益素餐忧。","黄河润千里，草木皆浸渍。","吾宗凡九人，继踵升官次。","门内无白丁，森森朱绿紫。","鹓行洎内职，亚尹州从事。","府掾监省官，高低皆清美。","悉由侥幸升，不因资考至。","朝廷悬爵秩，命之曰公器。","才者禄及身，功者赏于世。","非才及非功，安得专厚利。","寒衣内府帛，饥食太仓米。","不蚕复不穑，未尝勤四体。","虽然一家荣，岂塞众人议。","颙颙十目窥，龊龊千人指。","借问尔与吾，如何不自媿。","戒尔学立身，莫若先孝弟。","怡怡奉亲长，不敢生骄易。","战战复兢兢，造次必于是。","戒尔学干禄，莫若勤道艺。","尝闻诸格言，学而优则仕。","不患人不知，惟患学不至。","戒尔远耻辱，恭则近乎礼。","自卑而尊人，先彼而后己。","相鼠与茅鸱，宜鉴诗人刺。","戒尔勿旷放，旷放非端士。","周孔垂名教，齐梁尚清议。","南朝称八达，千载秽青史。","戒尔勿嗜酒，狂药非佳味。","能移谨厚性，化为凶险类。","古今倾败者，历历皆可记。","戒尔勿多言，多言者众忌。","苟不慎枢机，灾危从此始。","是非毁誉间，适足为身累。","举世重交游，拟结金兰契。","忿怨容易生，风波当时起。","所以君子心，汪汪淡如水。","举世好承奉，昂昂增意气。","不知承奉者，以尔为玩戏。","所以古人疾，蘧蒢与戚施。","举世重任侠，俗呼为气义。","为人赴急难，往往陷刑死。","所以马援书，殷勤戒诸子。","举世贱清素，奉身好华侈。","肥马衣轻裘，扬扬过闾里。","虽得市童怜，还为识者鄙。","我本羁旅臣，遭逢尧舜理。","位重才不充，戚戚怀忧畏。","深渊与薄冰，蹈之唯恐坠。","尔曹当悯我，勿使增罪戾。","闭门敛踪迹，缩首避名势。","名势不久居，毕竟何足恃。","物盛必有衰，有隆还有替。","速成不坚牢，亟走多颠踬。","灼灼园中花，早发还先萎。","迟迟涧畔松，鬰鬰含晚翠。","赋命有疾徐，青云难力致。","寄语谢诸郎，躁进徒为耳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-1b8afbad-6772-41fa-b092-84046cffb1a9","tags":[]},{"id":"poem-c3edf64e11acef5ca5bda970","title":"行路难三首 一","author":"李白","dynasty":"唐","verses":["金樽清酒斗十千，玉盘珍羞直万钱。","停杯投筯不能食，拔劒四顾心茫然。","欲渡黄河冰塞川，将登太行雪满山。","闲来垂钓碧溪上，忽复乘舟梦日边。","行路难，行路难，多岐路，今安在。","长风破浪会有时，直挂云帆济沧海。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c348bc2e-f50d-436b-88b7-c198d63dacfc","tags":["唐诗三百首","黄河","励志","友情","八年级下册(课内)","初中古诗","乐府","宴饮","哲理","怀才不遇"]},{"id":"poem-c3fa165219f0ae0bd801a3b9","title":"淳熙四年二月既望静江守臣张某奉诏劝农于郊乃作熙熙阳春之诗二十四章章四句以示父老俾告于其乡之人而歌之  其二二","author":"张栻","dynasty":"宋","verses":["粤以今日，劝相于郊。","乃作此诗，以懋尔劳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-7646121f-d845-4186-8ff5-36139982b8f5","tags":[]},{"id":"poem-c40f6d6fc2449c9a781c4e89","title":"赠李杭州","author":"张籍","dynasty":"唐","verses":["仙郎白首未归朝，应为苍生领六条。","惠化州人尽清净，高情野鹤与逍遥。","竹间虚馆无朝讼，山畔青田长夏苗。","终日政声长独坐，开门长望浙江潮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-01f4e76e-8cee-4b7e-a513-e1221a53300d","tags":[]},{"id":"poem-c4146534d939f6e33e2169e4","title":"杂兴","author":"卢仝","dynasty":"唐","verses":["意志未成百不解，见人富贵亦心爱。","等闲对酒呼三达，屠羊杀牛皆自在。","放心为乐笙歌攒，壮气激作风霜寒。","厨中玉馔盈金盘，方丈厌见嫌不餐。","飞鹰跃马实快性，唇腐齿烂空巑岏。","岂期福极翻成祸，祸成身诛家亦破。","昨朝惆怅不如君，今日悲君不如我。","否泰交加无定主，嬾学风云戢翎羽。","绿酒清琴好养生，出将入相无心取。","三五图书旧揣摩，五千道德新䂓矩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f008105c-31b5-4425-a657-0190d8ccb568","tags":[]},{"id":"poem-c414e46cca3529fcbfd51751","title":"浣溪沙·脂粉塘空遍绿苔","author":"纳兰性德","dynasty":"清","verses":["脂粉塘空遍绿苔。","掠泥营垒燕相催。","妒他飞去却飞回。","一骑近从梅里过，片帆遥自藕溪来。","博山香烬未全灰。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-20","tags":[]},{"id":"poem-c428477414213adc20c06ef6","title":"和吕知柔终南山诗（题拟）","author":"王思同","dynasty":"唐","verses":["料伊直拟冲霄汉，赖有青天压着头。","（见《册府元龟》卷九三九、卷九五四、《旧五代史》卷六五。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4248a124-50d8-43bd-8f77-64f8cca093a8","tags":["终南山"]},{"id":"poem-c42984e3939842b2e815382e","title":"戚氏·晚秋天","author":"柳永","dynasty":"宋","verses":["晚秋天。","一霎微雨洒庭轩。","槛菊萧疏，井梧零乱惹残烟。","凄然。","望江关。","飞云黯淡夕阳间。","当时宋玉悲感，向此临水与登山。","远道迢递，行人凄楚，倦听陇水潺。","正蝉吟败叶，蛩响衰草，相应喧喧。","孤馆度日如年。","风露渐变，悄悄至更阑。","长天净，绛河清浅，皓月婵娟。","思绵绵。","夜永对景，那堪屈指，暗想从前。","未名未禄，绮陌红楼，往往经岁迁延。","帝里风光好，当年少日，暮宴朝欢。","况有狂朋怪侣，遇当歌、对酒竞留连。","别来迅景如梭，旧游似梦，烟水程何限。","念利名、憔悴长萦绊。","追往事、空惨愁颜。","漏箭移、稍觉轻寒。","渐呜咽、画角数声残。","对闲窗畔，停灯向晓，抱影无眠。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-148","tags":["宋词三百首"]},{"id":"poem-c430d99289970a5bd3e4c310","title":"秋江送别","author":"无名氏《张协状元》","dynasty":"元","verses":["徐徐步野径，晓痕青柳弄金。","东风尚料峭，丽日升寒渐轻。","(生出)记得年时投上国，早一年珠泪泠。","此山又登，此身渐亨，是你否极还泰生。","(旦)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2678","tags":[]},{"id":"poem-c43b4cf0d876c8cac6e1db73","title":"水调歌头·今日俄重九","author":"韩元吉","dynasty":"宋","verses":["今日俄重九，莫负菊花开。","试寻高处，携手蹑屐上崔嵬。","放目苍岩千仞。","云护晓霜成阵。","知我与君来。","古寺倚修竹，飞槛绝纤埃。","笑谈间，风满座，酒盈杯。","仙人跨海，休问随处是蓬莱。","落日平原西望。","鼓角秋深悲壮。","戏马但荒台。","细把茱萸看，一醉且徘徊。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-830","tags":[]},{"id":"poem-c43d0af228302a1abaeb645c","title":"题妓王福娘墙 二","author":"孙棨","dynasty":"唐","verses":["寒绣衣裳饷阿娇，新团香兽不禁烧。","东邻起样裙腰阔，剩蹙黄金线几条。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a55c2233-1ef7-4b7c-bd37-20f801d512b9","tags":[]},{"id":"poem-c43e0386ed84f39d0b1dd9fe","title":"友人见访不值因寄","author":"唐求","dynasty":"唐","verses":["门户寒江近，篱墙野树深。","晚风摇竹影，斜日转山阴。","砌觉披秋草，床惊倒古琴。","更闻邻舍说，一只鹤来寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f1613ad5-4202-4972-9131-47bc15f4f193","tags":[]},{"id":"poem-c43e6e8fe852119f98e7be8f","title":"小游仙诗九十八首 六十九","author":"曹唐","dynasty":"唐","verses":["笑擎云液紫瑶觥，共请云和碧玉笙。","花下偶然吹一曲，人间因织董双成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e8d6113a-85cf-49b1-a2d5-2f20aef89ae5","tags":[]},{"id":"poem-c440c8a44d18f96848e55f53","title":"平江太守李宝谟移漕荆湘  其一","author":"释居简","dynasty":"宋","verses":["荆溪溪上传，接畛使君贤。","行旅归如市，羁游亟受廛。","丰储优郡计，薄歛裕民天。","谁似山阴叟，临行赠一钱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-7170c4e3-8bc0-407c-935d-834ea338b40d","tags":[]},{"id":"poem-c447b11e9da70c9c881d4e56","title":"孤雁","author":"王镃","dynasty":"宋","verses":["叫入青云忆弟兄，影随双翮见分明。","黄昏独过秋江上，自拣芦花歇又惊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-05a3a57f-35e2-4e39-9910-aae4a533b9cd","tags":[]},{"id":"poem-c44844c8","title":"墨梅","author":"王冕","dynasty":"元","verses":["我家洗砚池头树，朵朵花开淡墨痕。","不要人夸好颜色，只留清气满乾坤。"],"enabled":true,"collection":"历代名篇","source":"王冕《竹斋集》题画诗《墨梅》，采用“我家洗砚池头树”通行本。","tags":["咏物","梅花"]},{"id":"poem-c44dc85b915214eeda7949cd","title":"郊庙歌辞 昭德皇后庙乐章 永和","author":"不详","dynasty":"唐","verses":["穆清庙，荐严禋。","昭礼备，和乐新。","望灵光，集元辰。","祚无极，享万春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-389ab6fd-17b0-4633-af04-f1f4d9985116","tags":[]},{"id":"poem-c44df0ddf24915d759b42b70","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(小旦)是二更鼓了。","冬冬二鼓，则叶敲窗纸，响扑簌聒闷耳，难禁这般萧索，这般岑寂。","骨肉到此，到此你东我西，去又无门，住又无依倚，伤心怎生，怎生街头上睡？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3026","tags":[]},{"id":"poem-c45c429be26525b41585d513","title":"浣溪沙·一只横钗坠髻丛","author":"毛熙震","dynasty":"五代","verses":["一只横钗坠髻丛，静眠珍簟起来慵，绣罗红嫩抹酥胸。","羞敛细蛾魂暗断，困迷无语思犹浓，小屏香霭碧山重。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-36","tags":[]},{"id":"poem-c45ca96e63ca6518c450408e","title":"郊庙歌辞 仪坤庙乐章 送神","author":"不详","dynasty":"唐","verses":["玉帛仪大，金丝奏广。","灵应有孚，冥征不爽。","降彼休福，歆兹禋享。","送乐有章，神麾其上。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5df204cd-62f9-4d08-baa7-2d75bae5a9dd","tags":[]},{"id":"poem-c464e3fc9edabe43fca6de2e","title":"杨叛儿","author":"徐凝","dynasty":"唐","verses":["哀怨杨叛儿，骀荡郎知否。","香死博山炉，烟生白门柳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b5ab2b31-9c18-457b-909b-17a6581d1fbd","tags":[]},{"id":"poem-c467564b70e5fa7e7928868c","title":"满宫花·雪霏霏","author":"魏承班","dynasty":"五代","verses":["雪霏霏，风凛凛，玉郎何处狂饮。","醉时想得纵风流，罗帐香帷鸳寝。","春朝秋夜思君甚，愁见绣屏孤枕。","少年何事负初心，泪滴缕金双衽。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-0","tags":[]},{"id":"poem-c46d718efe426c37cfa450a1","title":"闲游","author":"张籍","dynasty":"唐","verses":["终日不离尘土间，若为能见此身闲。","今朝暂共游僧语，更恨趋时别旧山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-555ea1b6-606e-4ff9-80f2-d1d1daf76166","tags":[]},{"id":"poem-c46daab946e532db28fcd97b","title":"清平乐·才听夜雨","author":"纳兰性德","dynasty":"清","verses":["才听夜雨，便觉秋如许。","绕砌蛩螀人不语，有梦转愁无据。","乱山千叠横江，忆君游倦何方。","知否小窗红烛。","照人此夜凄凉。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-68","tags":[]},{"id":"poem-c46ee02ef065f316a29edc81","title":"送李给事归徐州觐省","author":"孙逖","dynasty":"唐","verses":["列位登青琐，还乡复彩衣。","共言晨省日，便是昼游归。","春水经梁宋，晴山入海沂。","莫愁东路远，四牡正𬴂𬴂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6bfafcb5-a3c8-43b7-892d-179ca8445df4","tags":[]},{"id":"poem-c47ed73e6832aeb7e5f381dc","title":"野望","author":"杜甫","dynasty":"唐","verses":["西山白雪三奇戍，南浦清江万里桥。","海内风尘诸弟隔，天涯涕泪一身遥。","唯将迟暮供多病，未有涓埃荅圣朝。","跨马出郊时极目，不堪人事日萧条。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d77f340f-1a04-4c5b-9704-2536e4249c6b","tags":["唐诗三百首","七言律诗","写景","抒情"]},{"id":"poem-c485b06604ac5955d09830ba","title":"生查子·远山眉黛横","author":"张孝祥","dynasty":"宋","verses":["远山眉黛横，媚柳开青眼。","楼阁断霞明，帘幕春寒浅。","杯延玉漏迟，烛怕金刀剪。","明月忽飞来，花影和帘卷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-344","tags":[]},{"id":"poem-c48b740ba4adaa439e64375e","title":"点绛唇·小院新凉","author":"纳兰性德","dynasty":"清","verses":["小院新凉，晚来顿觉罗衫薄。","不成孤酌，形影空酬酢。","萧寺怜君，别绪应萧索。","西风恶，夕阳吹角，一阵槐花落。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-78","tags":[]},{"id":"poem-c48d16204849252cbee119ac","title":"刘泼帽","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［净］念我到此求科举，因不第、羞回乡里。","修书欲报娘和父，欲烦捎带，只怕相推阻。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8166","tags":[]},{"id":"poem-c48f8884397ae7ffe682f1cc","title":"冬末病中作二首 一","author":"贯休","dynasty":"唐","verses":["冬风吹草木，亦吹我病根。","故人久不来，冷落如丘园。","聃龙与摩诘，吁叹非不闻。","顾惟年少时，未合多忧懃。","风钟远孤枕，雪水流冻痕。","空余微妙心，期空静者论。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-530741a2-f841-4fa4-94cf-673df4f8a172","tags":[]},{"id":"poem-c49fb4a579b1262de1194988","title":"山中冬夜","author":"张乔","dynasty":"唐","verses":["寒叶风摇尽，空林鸟宿稀。","涧冰妨鹿饮，山雪阻僧归。","夜坐尘心定，长吟语力微。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6d853633-4327-42cd-aed2-ee371fe58ec5","tags":[]},{"id":"poem-c49fcb14a5c091fc3d248715","title":"杨柳枝·惯得娇云赶不开","author":"王质","dynasty":"宋","verses":["惯得娇云赶不开。","去还来。","淡光无可照楼台。","且停杯。","薄雨疏疏时几点，洒浮埃。","卖花未上担儿抬。","听他催。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-309","tags":[]},{"id":"poem-c4a1d0e6736dd9ce64b89050","title":"青谿","author":"王维","dynasty":"唐","verses":["言入黄花川，每逐青谿水。","随山将万转，趣途无百里。","声喧乱石中，色静深松里。","漾漾泛菱荇，澄澄映葭苇。","我心素已闲，清川澹如此。","请留盘石上，垂钓将已矣。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a0576d39-c4ac-4608-a4e2-249b6c31fd1d","tags":["唐诗三百首","五言古诗","托物寄情","山水"]},{"id":"poem-c4aa939078c7f08b0826cb49","title":"雪霁晨起","author":"李德裕","dynasty":"唐","verses":["雪覆寒溪竹，风卷野田蓬。","四望无竹迹，谁怜孤老翁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-275423ed-cfdb-4b5b-830e-cc40137333ee","tags":[]},{"id":"poem-c4acb5fb335c8e05e521e1c9","title":"酒泉子·曲槛小楼","author":"孙光宪","dynasty":"五代","verses":["曲槛小楼，正是莺花二月。","思无聊，愁欲绝，郁离襟。","展屏空对潇湘水，眼前千万里。","泪掩红，眉敛翠，恨沉沉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-17","tags":[]},{"id":"poem-c4ad5776ca5694af5ccfff7f","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["何须虑，不用焦，人世上离多欢会少。","大丈夫当万里封侯，肯守着故园空老？毕竟事君事亲一般道，人生怎全得忠和孝？却不见母死王陵归汉朝？(生唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5033","tags":[]},{"id":"poem-c4afcd763d242d0a64d229eb","title":"菩萨蛮 其四","author":"温庭筠","dynasty":"唐","verses":["翠翘金缕双㶉𫛶，水纹细起春池碧。","池上海棠梨，雨晴红满枝。","绣衫遮笑靥，烟草粘飞蝶。","青琐对芳菲，玉关音信稀。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-3","tags":[]},{"id":"poem-c4b2438b36d4048a3d609a73","title":"忆扬州","author":"徐凝","dynasty":"唐","verses":["萧娘脸下难胜泪，桃叶眉头易得愁。","天下三分明月夜，二分无赖是扬州。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2b7a8989-7aa2-4665-901e-6b979e4bbb2e","tags":[]},{"id":"poem-c4ba9c7678ecc83b4c37a97e","title":"喜皇甫郎中拜谕德兼集贤学士","author":"李端","dynasty":"唐","verses":["为郎三载后，宠命一朝新。","望苑迁词客，儒林拜丈人。","莺飞绮阁曙，柳拂画堂春。","几日调金鼎，诸君欲望尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9345bb4c-1059-4af4-9c1e-c75839490a66","tags":[]},{"id":"poem-c4bb50ae12fe91376b655a9b","title":"村中夜归","author":"王镃","dynasty":"宋","verses":["风报轻寒入暮天，滞行多被酒留连。","花村无月路全黑，竹屋有灯人未眠。","云气苍茫沉远树，春心浩荡怯啼鹃。","忽晴又雨都无准，泥污吟衫亦懒湔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-649bc948-53c6-465b-8de8-017174a12e66","tags":[]},{"id":"poem-c4c37fcaa023d45594f52db8","title":"琵琶仙·中秋","author":"纳兰性德","dynasty":"清","verses":["碧海年年，试问取、冰轮为谁圆缺。","吹到一片秋香，清辉了如雪。","愁中看、好天良夜，知道尽成悲咽。","只影而今，那堪重对，旧时明月。","花径里、戏捉迷藏，曾惹下萧萧井梧叶。","记否轻纨小扇，又几番凉热。","只落得，填膺百感，总茫茫、不关离别。","一任紫玉无情，夜寒吹裂。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-113","tags":[]},{"id":"poem-c4c389775c3b03fd9168237d","title":"郊庙歌辞 武后大享昊天乐章 一","author":"不详","dynasty":"唐","verses":["大阴凝至化，真耀蕴轩仪。","德迈娥台敞，仁高姒幄披。","扪天遂启极，梦日乃升曦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-0d9622c6-0120-4f70-ac8f-17996b69dd93","tags":[]},{"id":"poem-c4d04f02f1dfc4966c1759bd","title":"长相思·云一涡","author":"李煜","dynasty":"五代","verses":["云一涡，玉一梭。","澹澹衫儿薄薄罗，轻颦双黛螺。","秋风多，雨相和。","帘外芭蕉三两窠。夜长人奈何？"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-17","tags":[]},{"id":"poem-c4d20f78ed1988535bafb31a","title":"江神子・江城子·金银楼阁认蓬莱","author":"韩元吉","dynasty":"宋","verses":["金银楼阁认蓬莱。","晓烟开。","上崔嵬。","风引孤帆，谁道却船回。","鹏翼倚天鳌背稳，惊浪起，雪成堆。","翩翩黄鹤为谁来。","醉持杯。","共徘徊。","四面江声，脚底隐晴雷。","织女机头凭借问，何处更、有琼台。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-822","tags":[]},{"id":"poem-c4d5fa17f46f369bcdb39c85","title":"题静住寺钦用上人房","author":"马戴","dynasty":"唐","verses":["寺近朝天路，多闻玉珮音。","鉴人开慧眼，归鸟息禅心。","磬接星河曙，窗连夏木深。","此中能宴坐，何必在云林。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8ca6fcbc-49f0-4230-b3b2-710c35a33b40","tags":[]},{"id":"poem-c4d707e8614ad5b767763177","title":"唐享昊天乐 第一","author":"则天皇后","dynasty":"唐","verses":["太阴凝至化，真耀蕴轩仪。","德迈娥台敞，仁高[姒]幄披。","扪天遂启极，梦日乃升曦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-23c871de-760f-4030-a5f2-3abe14c67d01","tags":[]},{"id":"poem-c4db088fbb65dcf124e26fff","title":"采石","author":"华镇","dynasty":"宋","verses":["夜暗枭狐响，天明蛟蜃伏。","君子贵知几，乘时介多福。","中原昔不竞，淮海波涛蹙。","高视孙仲谋，雄心冀前躅。","大明将升腾，氛祲先驱逐。","周师东南指，淮澨归亭毒。","遗烬倚江流，荧荧怯风烛。","真人方远略，坠绪劳君续。","后至祇取羞，先迷庶能复。","时雨动民望，远猷走辰告。","密算结浮梁，长驱践平陆。","敌气沮飞渡，军势乘破竹。","鳞羽不及张，巢窟骇倾覆。","百年厓石棱，镌刻犹在目。","风涛杳不作，水落秋山足。","留与钓鱼舟，穿维宛相属。","由来一带水，未胜长城曲。","道梗叛或易，时清去还速。","何必凿秦淮，佳气自消缩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-0589ad83-5534-44f9-b87f-b7841871d1c2","tags":[]},{"id":"poem-c4de37d7587820f70193f283","title":"宫词  其九四","author":"张公庠","dynasty":"宋","verses":["雪罢严寒殆不禁，紫宸朝退禁门深。","君恩委曲人知否，数盏香醪抵百金。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-925d7973-04a4-46f1-a589-32a2ca2ef745","tags":[]},{"id":"poem-c4e9ba720a511fdf460a89af","title":"西溪次韵九首  其二","author":"刘跂","dynasty":"宋","verses":["携手西溪陌，懽颜共举觞。","云山满目静，风月一襟凉。","但得杯中玉，那知鬓后霜。","何妨击尊破，故作听歌长。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-3066979f-c78d-42ff-a82f-f0b361d5201c","tags":[]},{"id":"poem-c4f5175a82ca9bf06e2d3784","title":"蝶恋花·桃萼新香梅落后","author":"周邦彦","dynasty":"宋","verses":["桃萼新香梅落后。","暗叶藏鸦，苒苒垂亭牖。","舞困低迷如著酒。","乱丝偏近游人手。","雨过朦胧斜日透。","客舍青青，特地添明秀。","莫话扬鞭回别首。","渭城荒远无交旧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-440","tags":[]},{"id":"poem-c4f694752ea90d9a6e9f9680","title":"河满子","author":"薛逢","dynasty":"唐","verses":["系马宫槐老，持杯店菊黄。","故交今不见，流恨满川光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c1651595-e5a0-4960-a1ce-3373f5e3726b","tags":[]},{"id":"poem-c4fc7e7617fa9aa6302827f1","title":"古镜","author":"若虚","dynasty":"唐","verses":["轩后红炉独铸成，藓痕磨落月轮呈。","万般物象皆能鉴，一个人心不可明。","匣内乍开鸾凤活，台前高挂鬼神惊。","百年肝胆堪将比，祗怕看频素发生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-84e24966-b11c-4fbc-90ef-668d93bb0941","tags":[]},{"id":"poem-c504134b85ea25434d913ee0","title":"春秋战国门 颜叔子","author":"周昙","dynasty":"唐","verses":["夜雨邻娃告屋倾，一宵从寄念悲惊。","诚知独处从烧烛，君子行心要自明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-996e3eff-4996-4514-b79e-1bef62c5c6bf","tags":[]},{"id":"poem-c512267539b4c97ab7fb5623","title":"后园凿井歌","author":"李贺","dynasty":"唐","verses":["井上辘轳床上转，水声繁，弦声浅。","情若何，荀奉倩。","城头日，长向城头住。","一日作千年，不须流下去。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2b791d3a-fd4f-404a-be8a-28299bcd819d","tags":["夫妻","爱情","生活"]},{"id":"poem-c51f72104aca7f3ba2f96c46","title":"怨词二首 一","author":"崔国辅","dynasty":"唐","verses":["妾有罗衣裳，秦王在时作。","为舞春风多，秋来不堪著。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-2483104b-9d1a-4376-b4af-a864212d0c9d","tags":[]},{"id":"poem-c527f2e4210473b1c9b50bc0","title":"收江南","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(生)呀！早知道这般样拆散呵，谁待要赴春闱？便做到腰金衣紫待何如？说来又恐外人知，端的是不如布衣，端的是不如布衣！俺只索要低声啼哭自伤悲。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8274","tags":[]},{"id":"poem-c52903d280d986a9f9ad625a","title":"少年游·如今田野谩抛春","author":"晁补之","dynasty":"宋","verses":["如今田野谩抛春。","红雨掩衡门。","懒读诗书，欠伸扶杖，几案任生尘。","纵教便向东山老，谁知是个中人。","莫怪年来，倦寻城市，嫌我性情真。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-170","tags":[]},{"id":"poem-c53464df5ef0c825977db0e2","title":"送归中丞使新罗","author":"皇甫曾","dynasty":"唐","verses":["南幰衔恩去，东夷泛海行。","天遥辞上国，水尽到孤城。","已变炎凉气，仍愁浩淼程。","云涛不可极，来往见双旌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-32c87342-3c08-4cff-952c-67eda7fb9d46","tags":[]},{"id":"poem-c53a5d5922d030112934987c","title":"贺明朝·忆昔花间相见后","author":"欧阳炯","dynasty":"五代","verses":["忆昔花间相见后，只凭纤手，暗抛红豆。","人前不解，巧传心事。","别来依旧，辜负春昼。","碧罗衣上蹙金绣，睹对对鸳鸯，空裛泪痕透。","想韶颜非久，终是为伊，只恁偷瘦。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-10","tags":[]},{"id":"poem-c53d7a2228e10fd69e1ad8e6","title":"临江仙·追想京都全盛日","author":"张纲","dynasty":"宋","verses":["追想京都全盛日，蓬弧初记生时。","朝来朱绂照庭闱。","谁知衰谢老，还有宁馨儿。","休记蓝田生美玉，举杯听取歌词。","年方强仕未应迟。","高风轻借便，一鹗看横飞。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-646","tags":[]},{"id":"poem-c54f06f6852da0c3fc6dc797","title":"其日雨中闻姚黄开戏成诗二章呈子骏尧夫  其二","author":"司马光","dynasty":"宋","verses":["小雨留春春未归，好花虽有恐行稀。","劝君披取鱼蓑去，走看姚黄判湿衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-b0008d07-0833-49af-baf8-f4ddbd926d28","tags":[]},{"id":"poem-c54f0ac6c7bc028fa3eabdea","title":"折桂令","author":"施惠《幽闺记》","dynasty":"元","verses":["(外)古人言自有权舆，能者迁之，否则存之。","(净)说得好！说得好！你说圣上不如太王。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2862","tags":[]},{"id":"poem-c56336cd4ed2ad9886d775cd","title":"魏宫词","author":"崔国辅","dynasty":"唐","verses":["朝日照红妆，拟上铜雀台。","画眉犹未了，魏帝使人催。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ee46821d-7fb8-4918-9e62-558c884245b6","tags":[]},{"id":"poem-c563cedf8c0cfc66e7faac81","title":"郊庙歌辞 享懿德太子庙乐章 送文舞迎武舞","author":"不详","dynasty":"唐","verses":["八音协奏陈金石，六佾分行整礼容。","沧溟赴海还称少，素月开轮即是重。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-2fd8d994-fa15-4dd6-9619-af4802e819fc","tags":[]},{"id":"poem-c576385bfdf30a03c11af463","title":"劝人 二","author":"义存","dynasty":"唐","verses":["若切老婆心，劝君莫掠虚。","忽遇明眼人，相逢笑杀渠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7980ec79-4f96-4da4-a915-f92a9a5fc7b9","tags":[]},{"id":"poem-c580f7c79253126abf4a507c","title":"北曲得胜令","author":"萧德祥《小孙屠》","dynasty":"元","verses":["则笑卓氏女忒心痴，它被这睡魔正厮禁持。","则想醉里乾坤大，全不想花间云雨期。","身靠着屏围，魂梦谁根底？酒病好难医，今朝醒觉迟。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8620","tags":[]},{"id":"poem-c582e1c1d5fc7a3281184d2c","title":"宫词  其五六","author":"张公庠","dynasty":"宋","verses":["倦饮情怀春晼晚，宫槐新叶未成阴。","和风习习帘帘卷，轻絮翩翩院院深。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-343b19ac-a00a-4f91-9014-6a89553367e4","tags":[]},{"id":"poem-c585d7755146c75aaa67efda","title":"金陵怀古","author":"司空曙","dynasty":"唐","verses":["辇路江枫暗，宫庭野草春。","伤心庾开府，老作北朝臣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2bba5a88-ee75-4eb5-9ab9-4b6f27402147","tags":[]},{"id":"poem-c58c09e9dd47fb06eae6e4fd","title":"和立斋岁寒歌五章  其二","author":"王柏","dynasty":"宋","verses":["忆昔坚保兮铭著心腑，故迹堙芜兮茫茫坠绪。","瞻翠碧之万竿兮犹有遗矩，岁寒之句俨然如覩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-0219c0cd-22f7-48e7-89d4-eac1bdb230f9","tags":[]},{"id":"poem-c594448b24a1c5862d1f53be","title":"春晓","author":"孟浩然","dynasty":"唐","verses":["春眠不觉晓，处处闻啼鸟。","夜来风雨声，花落知多少。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-cb168b3b-d104-4df7-9868-1e1225ddb941","tags":["唐诗三百首","春","写景","一年级下册","惜春","五言绝句","小学古诗"]},{"id":"poem-c5974d6e30df9c62a1255599","title":"诉衷情·涌金门外小瀛洲","author":"仲殊","dynasty":"宋","verses":["涌金门外小瀛洲。","寒食更风流。","红船满湖歌吹，花外有高楼。","晴日暖，淡烟浮。","恣嬉游。","三千粉黛，十二阑干，一片云头。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-913","tags":[]},{"id":"poem-c59f44031efc859225f2cdaa","title":"昭台行  其二","author":"释居简","dynasty":"宋","verses":["将军发机阴中的，功如熟稼生螟𫋌。","母仪天下极尊荣，非道得之非所得。","一朝乐去悲相随，霜露既降风凄其。","惸惸吊景将安之，不自为计终奚为。","关中旧约三章法，法当夷宗雠逆节。","况复曾孙诛大臣，项背相望眉不颦。","昭台不隔昭阳路，花落鸟啼春几度。","麟角凤觜皆可煎，惆怅君恩非断弦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-42219800-ae66-46ab-880a-3429fad12700","tags":[]},{"id":"poem-c5a06c01f29b48a953f167c4","title":"登游齐山","author":"许坚","dynasty":"宋","verses":["星使南驰入楚重，此山偏得驻行踪。","落花满地月华冷，寂寞旧山三四峰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-431b1898-bd46-4601-86f7-da93cc3d6ee7","tags":[]},{"id":"poem-c5a2069b6e4509006963095c","title":"将仲子","author":"佚名","dynasty":"先秦","verses":["将仲子兮，无逾我里，无折我树杞。岂敢爱之？畏我父母。仲可怀也，父母之言亦可畏也。","将仲子兮，无逾我墙，无折我树桑。岂敢爱之？畏我诸兄。仲可怀也，诸兄之言亦可畏也。","将仲子兮，无逾我园，无折我树檀。岂敢爱之？畏人之多言。仲可怀也，人之多言亦可畏也。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-75","tags":[]},{"id":"poem-c5b4ce0c04d3b97f2a276907","title":"春宫词","author":"李咸用","dynasty":"唐","verses":["风和气淑宫殿春，感阳体解思君恩。","眼光滴滴心振振，重瞳不转忧生民，女当为妾男当臣。","男力百岁在，女色片时新。","用不用，唯一人。","敢放天宠私微身，六宫万国教谁宾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-939820b9-39e1-45c4-bf95-2680b06a664e","tags":[]},{"id":"poem-c5c952f1c12dc1c5d01e1c72","title":"申胡子觱篥歌","author":"李贺","dynasty":"唐","verses":["颜热感君酒，含嚼芦中声。","花娘𥮾绥妥，休睡芙蓉屏。","谁截太平管，列点排空星。","直贯开花风，天上驱云行。","今夕岁华落，令人惜平生。","心事如波涛，中坐时时惊。","朔客骑白马，剑弝悬兰缨。","俊健如生猱，肯拾蓬中萤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7344a621-9c5b-435b-ab03-5bce85d24ce2","tags":[]},{"id":"poem-c5e477d1912cd50e2b1178b6","title":"应天长·瑟瑟罗裙金线缕","author":"顾敻","dynasty":"五代","verses":["瑟瑟罗裙金线缕，轻透鹅黄香画袴。","垂交带，盘鹦鹉，袅袅翠翘移玉步。","背人匀檀注，慢转横波偷觑。","敛黛春情暗许，倚慵不语。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-18","tags":[]},{"id":"poem-c5ed29b08560d1d5cfd0f871","title":"赠小苏","author":"关景仁","dynasty":"宋","verses":["昔日闻苏小，今朝见小苏。","未知苏小貌，得似小苏无。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-fec62c94-0981-4f5e-932a-f228532ae98d","tags":[]},{"id":"poem-c5f076471952f2a256db620f","title":"候人","author":"佚名","dynasty":"先秦","verses":["彼候人兮，何戈与祋。彼其之子，三百赤芾。","维鹈在梁，不濡其翼。彼其之子，不称其服。","维鹈在梁，不濡其咮。彼其之子，不遂其媾。","荟兮蔚兮，南山朝𬯀。婉兮娈兮，季女斯饥。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-150","tags":[]},{"id":"poem-c5f4b65e9ee37c83568466ad","title":"伯时二马  其二","author":"释居简","dynasty":"宋","verses":["市骏爰从画骏谋，何如脱鞅纵骅骝。","青青许负双眸子，不识骅骝只相牛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9a7e0ee8-1cc7-4649-ba22-8cb627fda34d","tags":[]},{"id":"poem-c5f85aa50629fbc3e951e6a3","title":"近榆亭  其七","author":"陈造","dynasty":"宋","verses":["少日接为构，无何了桑榆。","邀食有余地，何事须千奴。","此亭与此木，到眼聊为娱。","五诗信睡语，定博君卢胡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-9dc4a03d-03dd-478c-8b5f-d039088cb5d6","tags":[]},{"id":"poem-c5febd5a6ba8cc009ea5ee5f","title":"与友人会","author":"杨凝","dynasty":"唐","verses":["蝉吟槐蘂落，的的是愁端。","病觉离家远，贫知处事难。","真交无所隐，深语有余欢。","未必闻歌吹，羁心得𫏐宽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a9ed41c1-862e-4dea-af90-f5de5a02e814","tags":[]},{"id":"poem-c6007d333ffd4c28ff2256b8","title":"临江仙·洞庭波浪飐晴天","author":"牛希济","dynasty":"五代","verses":["洞庭波浪飐晴天，君山一点凝烟。","此中真境属神仙，玉楼珠殿，相映月轮边。","万里平湖秋色冷，星辰垂影参然。","桔林霜重更红鲜，罗浮山下，有路暗相连。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-39","tags":[]},{"id":"poem-c602ee72c4e006c8bceeea9e","title":"重忆山居六首 罗浮山","author":"李德裕","dynasty":"唐","verses":["龙伯钓鼇时，蓬莱一峰坼。","飞来碧海畔，遂与三山隔。","其下多长溪，潺湲淙乱石。","知君分如此，赠逾荆山璧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b6ccc575-b4f1-4027-b442-811fc39a451d","tags":[]},{"id":"poem-c6069bfdab9e1e3409b0f78b","title":"阮郎归·天边金掌露成霜","author":"晏几道","dynasty":"宋","verses":["天边金掌露成霜。","云随雁字长。","绿杯红袖称重阳。","人情似故乡。","兰佩紫，菊簪黄。","殷勤理旧狂。","欲将沈醉换悲凉。","清歌莫断肠。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-30","tags":["宋词三百首"]},{"id":"poem-c60a80223c89b31c8aa1b6ab","title":"和叔崇两绝  其一","author":"王柏","dynasty":"宋","verses":["道心常要摄人心，有德之人必有隣。","愧我空虚无一善，安能交义契兰金。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-4b0e0b61-0f09-432c-a015-a6419d0046db","tags":[]},{"id":"poem-c6279ac94e92e0cccfd2da27","title":"酬兵部李侍郎晚过东厅之作","author":"包佶","dynasty":"唐","verses":["酒礼慙先祭，刑书已旷官。","诏驰黄纸速，身在绛纱安。","圣位登堂静，生徒跪席寒。","庭槐暂摇落，幸为入春看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cd892edd-f7b3-4d5c-bacc-8b1a02a0564a","tags":[]},{"id":"poem-c63958d164d8fb424b8242e3","title":"拟君子有所思二首 一","author":"贯休","dynasty":"唐","verses":["我爱正考甫，思贤作商颂。","我爱扬子云，理乱皆如凤。","振衣中夜起，露花香旖旎。","扑碎骊龙明月珠，敲出凤皇五色髓。","陋巷萧萧风㭊㭊，缅想斯人胜珪璧。","寂寥千载不相逢，无限区区尽虚掷。","君不见沈约道，佳人不在兹，春光为谁惜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-0b24845c-c5cb-4e7f-aa86-3cd08e92c742","tags":[]},{"id":"poem-c63caba0047b219e53385d41","title":"秦镜","author":"张佐","dynasty":"唐","verses":["楼上秦时镜，千秋独有名。","菱花寒不落，冰质夏长清。","龙在形难掩，人来胆易呈。","升台宜远照，开匣乍藏明。","皎色新磨出，圆规旧铸成。","愁容如可鉴，当欲拂尘缨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-f0aea48b-98b5-42de-8986-3d2e80540dd5","tags":[]},{"id":"poem-c648465356e08f770663d046","title":"蝶恋花·满到十分人望尽","author":"黄裳","dynasty":"宋","verses":["满到十分人望尽。","仙桂无根，到处留光景。","听我尊前欢未竟。","金卮已弄寒蟾影。","银色界中风色定。","散了浮云，宝匣初开镜。","归去不须红烛影。","天边自与人相趁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-631","tags":[]},{"id":"poem-c648db0fcf85c43b0e50e81d","title":"蝶恋花·几许伤春春复暮","author":"贺铸","dynasty":"宋","verses":["几许伤春春复暮。","杨柳清阴，偏碍游丝度。","天际小山桃叶步。","白苹花满湔裙处。","竟日微吟长短句。","帘影灯昏，心寄胡琴语。","数点雨声风约住。","朦胧淡月云来去。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-106","tags":["宋词三百首"]},{"id":"poem-c64eadbca0ae2d7a030da2e3","title":"秋宿经上人房","author":"李洞","dynasty":"唐","verses":["江房无叶落，松影带山高。","满寺中秋月，孤窗入夜涛。","旧真悬石壁，衰发落铜刀。","卧听晓耕者，与师知苦劳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-065f277f-9101-4a32-bb53-1707e1d645f8","tags":[]},{"id":"poem-c65328df912fb64c86cc22dd","title":"杨柳枝·织锦机边莺语频","author":"温庭筠","dynasty":"唐","verses":["织锦机边莺语频，停梭垂泪忆征人。","塞门三月犹萧索，纵有垂杨未觉春。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-36","tags":[]},{"id":"poem-c655a8c2f904d2347789b7cb","title":"峡哀 六","author":"孟郊","dynasty":"唐","verses":["谗人峡虬心，渴罪呀然浔。","所食无直肠，所语饶枭音。","石齿嚼百泉，石风号千琴。","幽哀莫能远，分雪何由寻。","月魄高卓卓，峡窟清沉沉。","衔诉何时明，抱痛已不禁。","犀飞空波涛，裂石千嵚岑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-06de6be3-0257-4ee5-9fde-2e2fef90ad9b","tags":[]},{"id":"poem-c6563f013d6421c0831b6e59","title":"旅怀","author":"崔涂","dynasty":"唐","verses":["水流花谢两无情，送尽东风过楚城。","蝴蝶梦中家万里，杜鹃枝上月三更。","故园书动经年绝，华发春催两鬓生。","自是不归归便得，五湖烟景有谁争。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-旅懷","tags":[]},{"id":"poem-c658937611ca8e7e832f4fb3","title":"采桑子·平生为爱西湖好","author":"欧阳修","dynasty":"宋","verses":["平生为爱西湖好，来拥朱轮。","富贵浮云。","俯仰流年二十春。","归来恰似辽东鹤，城郭人民。","触目皆新。","谁识当年旧主人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-607","tags":["西湖"]},{"id":"poem-c660ae5f6a76ae26e43f17a0","title":"惜春令·春梦无凭犹懒起","author":"杜安世","dynasty":"宋","verses":["春梦无凭犹懒起。","银烛尽、画帘低垂。","小庭杨柳黄金翠，桃脸两三枝。","妆阁慵梳洗。","闷无绪、玉箫抛掷。","絮飘纷纷人疏远，空对日迟迟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-873","tags":[]},{"id":"poem-c660fadce212ef09594726c0","title":"偈颂（幷序○序为南岳齐己撰） 二十四","author":"居遁","dynasty":"唐","verses":["世人无心不能治，致祸愁生累及眉。","一朝体得心无事，眉放毫光自不知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6765e15d-7916-4f6a-9e05-25599ffea48a","tags":["衡山"]},{"id":"poem-c66ecce36ada4ad2ed893d7c","title":"见王贞白","author":"裴说","dynasty":"唐","verses":["共贺登科后，明宣入紫宸。","又看重试榜，还见苦吟人。","此得名浑别，归来话亦新。","分明一枝桂，堪动楚江滨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-d84a1d6c-b0a6-43a0-83f7-b3c5dabdbcf0","tags":[]},{"id":"poem-c671908025ed47a908c33aaa","title":"颂古七十六首  其六三","author":"释士珪","dynasty":"宋","verses":["风头稍硬难安立，暖气才通瞌睡来。","却笑明招闲费力，无端两处强差排。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-b5bf1a66-52f8-4929-ac26-8d226d5f46ce","tags":[]},{"id":"poem-c672ecfd6a0a3c25e3b8777b","title":"春日偶成","author":"程颢","dynasty":"宋","verses":["云淡风轻近午天，傍花随柳过前川。","时人不识余心乐，将谓偷闲学少年。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-春日偶成","tags":[]},{"id":"poem-c6818747627539fbb4abc5ef","title":"复吴秘正五诗  其四","author":"陈造","dynasty":"宋","verses":["作宰古尚教，宓齐但横琴。","唐吏犹易为，读书或松林。","一从来海濒，琴书暗尘侵。","俗有古今异，鞭扑违寸心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-1d135141-7a2d-4c7b-9482-04591e1dec5c","tags":[]},{"id":"poem-c68bb4a082b50795d08c887d","title":"次诸公诗韵","author":"陈造","dynasty":"宋","verses":["墙围护风烟，簷影纳红绿。","城西百弓地，论价指和玉。","沧浪取具体，辋川俨遗躅。","年时得小憩，振衣休汗足。","山灵不留人，定复厌枨触。","坐想散花女，深堂伴金粟。","今年桃李月，僮马几装束。","竟成梦魂到，永叹春事促。","此亦志愿违，世有谿壑欲。","似闻偕六逸，碧酒仍艳曲。","风鹤羽人下，露花妃子浴。","诗卷肯属我，为洗颜面俗。","元亮晚耒耜，弥明旧符箓。","可须白月前，熠熠度萤烛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-eff48515-9c42-42c5-815f-2a1a53102574","tags":[]},{"id":"poem-c68d5c92650a6a0ee540712d","title":"酬王哦松八景  其一","author":"释居简","dynasty":"宋","verses":["横玉临江展碧纨，冯夷庭院水晶寒。","天教两赋酬风雅，不谓人闲作画看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9c0d5054-73de-4582-a4be-9e4a9177dc6c","tags":[]},{"id":"poem-c6ab01807b66879ff24d1cea","title":"观竞渡","author":"薛逢","dynasty":"唐","verses":["三月三日天清明，杨花绕江啼晓莺。","使君未出郡斋内，江上已闻齐和声。","使君出时皆有引，马前已被红旗阵。","两岸罗衣破鼻香，银钗照日如霜刃。","鼓声三下红旗开，两龙跃出浮水来。","擢影斡波飞万劒，鼓声劈浪鸣千雷。","雷声冲急波相近，两龙望标目如瞬。","江上人呼霹雳声，竿头彩挂虹霓晕。","前船抢水已得标，后船失势空挥桡。","疮眉血首争不定，输岸一朋心似烧。","只将标示输赢赏，两岸十舟五来往。","须臾戏罢各东西，竞脱文身请书上。","吾今细观竞渡儿，何殊当路权相持。","不思得所各休去，会到摧舟折楫时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c0944f9f-23d3-4187-9968-bf7a253903dd","tags":["端午节"]},{"id":"poem-c6aeba1891d8808b55e7ad39","title":"颂","author":"释德韶","dynasty":"宋","verses":["暂下高峰已显扬，般若圜通遍十方。","人天浩浩无差别，法界纵横处处彰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-0768d60c-8155-4683-89d0-d428b894ab3a","tags":[]},{"id":"poem-c6b9c4043138299d78071756","title":"喻道","author":"李咸用","dynasty":"唐","verses":["汉武秦皇漫苦辛，那思俗骨本含真。","不知流水潜催老，未悟三山也是尘。","牢落沙丘终古恨，寂寥函谷万年春。","长生客待仙桃饵，月里婵娟笑煞人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b32e2b62-59de-4268-99de-e4e54adc0082","tags":[]},{"id":"poem-c6c18430fd2d27f1334e1eea","title":"寄韩谏议","author":"杜甫","dynasty":"唐","verses":["今我不乐思岳阳，身欲奋飞病在床。","美人娟娟隔秋水，濯足洞庭望八荒。","鸿飞冥冥日月白，青枫叶赤天雨霜。","玉京群帝集北斗，或骑骐𬴊翳凤皇。","芙蓉旌旗烟雾乐，影动倒景摇潇湘。","星宫之君醉琼浆，羽人稀少不在旁。","似闻昨者赤松子，恐是汉代韩张良。","昔随刘氏定长安，帷幄未改神惨伤。","国家成败吾岂敢，色难腥腐餐风香。","周南留滞古所惜，南极老人应寿昌。","美人胡为隔秋水，焉得置之贡玉堂。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6d303931-f900-4f29-a8b9-caea611a521f","tags":["唐诗三百首","洞庭湖","游仙","七言古诗"]},{"id":"poem-c6c34897e2d9ba75b5ab0200","title":"汤泉应制·清时礼乐萃朝端","author":"纳兰性德","dynasty":"清","verses":["清时礼乐萃朝端，次第郊原引玉銮。","河岳千年归带砾，寝园三月拜衣冠。","便从畿甸亲民隐，更启神泉示从官。","非独炎灵钟坎德，恩波深处不知寒。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-236","tags":[]},{"id":"poem-c6d7087a09d83fb89bd04e48","title":"简施芸隠","author":"宋伯仁","dynasty":"宋","verses":["雪后东风作峭寒，客怀零乱客眉攒。","杭州虽近西湖月，宁似湖州把钓竿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b05b5742-b6a7-4a21-aa5a-5eb2a19a3d9e","tags":["西湖"]},{"id":"poem-c6dba4b13d669d8e9df29142","title":"离乱后寄九峰和尚二首 一","author":"贯休","dynasty":"唐","verses":["乱后知深隐，庵应近石楼。","异香因雪歇，仙果落池浮。","诗老全抛格，心空未到头。","还应嫌笑我，世路独悠悠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2bd335a8-d8f6-41ab-bf90-eb0c68a3c72d","tags":[]},{"id":"poem-c6dc59e7d904c0d8b0918103","title":"赵府录官满  其一","author":"释居简","dynasty":"宋","verses":["平反固尽情，此话久弥新。","动以中为的，居嫌恕寡隣。","暗萤方自照，屈蠖倩谁伸。","好在庭前树，长怀雪后春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-fc51e1e3-2d56-4302-a278-b512861fc8f5","tags":[]},{"id":"poem-c6e071e70c00c84bac7da65e","title":"折柳篇","author":"许景先","dynasty":"唐","verses":["春色东来度渭桥，青门垂柳百千条。","长杨西连建章路，汉家林苑纷无数。","萦花始遍合欢枝，游丝半罥相思树。","春楼初日照南隅，柔条垂绿扫金铺。","宝钗新梳倭堕髻，锦带交垂连理襦。","自怜柳塞淹戎幕，银烛长啼愁梦著。","芳树朝催玉管新，春风夜染罗衣薄。","城头杨柳已如丝，今年花落去年时。","折芳远寄相思曲，为惜容华难再持。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fdef87c4-ea2c-4314-a05c-c2a3a2020d5b","tags":[]},{"id":"poem-c6e10c4ca00e44d22da422f1","title":"题临安邸","author":"林升","dynasty":"宋","verses":["山外青山楼外楼，西湖歌舞几时休。","暖风薰得游人醉，直把杭州作汴州。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題臨安邸","tags":[]},{"id":"poem-c6e1c1fde17380b344e3c3fb","title":"少年游·芙蓉花发去年枝","author":"晏殊","dynasty":"宋","verses":["芙蓉花发去年枝。","双燕欲归飞。","兰堂风软，金炉香暖，新曲动帘帷。","家人拜上千春寿，深意满琼卮。","绿鬓朱颜，道家装束，长似少年时。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-477","tags":[]},{"id":"poem-c6e363ae2774c0606ef8dd0f","title":"水调歌头","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["秋灯明翠巾莫，夜案览芸编。","今来古往，其间故事几多般。","少甚佳人才子，也有神仙幽怪，琐碎不堪观。","正是：不关风化体，纵好也徒然。","论传奇，乐人易，动人难。","知音君子，这般另做眼儿看。","休论插科打诨，也不寻宫数调，只看子孝与妻贤。","骅骝方独步，万马敢争先？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4907","tags":[]},{"id":"poem-c6e46207e6f9f06e08d4109e","title":"鹳雀楼晴望","author":"马戴","dynasty":"唐","verses":["尧女楼西望，人怀太古时。","海波通禹凿，山木闭虞祠。","鸟道残虹挂，龙潭返照移。","行云如可驭，万里赴心期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-26234f56-e269-46e5-bcf0-25b3b422a3dd","tags":[]},{"id":"poem-c6e49bc563957bb884b2b22d","title":"乾元中寓居同谷县作歌七首 四","author":"杜甫","dynasty":"唐","verses":["有妹有妹在钟离，良人早殁诸孤痴。","长淮浪高蛟龙怒，十年不见来何时。","扁舟欲往箭满眼，杳杳南国多旌旗。","鸣呼四歌兮歌四奏，林猨为我啼清昼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d9068fa3-4453-4d44-845f-1a4ab4186a1a","tags":[]},{"id":"poem-c6e831c74ffe416393699e52","title":"木兰花令·凌歊台上青青麦","author":"黄庭坚","dynasty":"宋","verses":["凌歊台上青青麦。","姑熟堂前馀翰墨。","暂分一印管江山，稍为诸公分皂白。","江山依旧云空碧。","昨日主人今日客。","谁分宾主强惺惺，问取矶头新妇石。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-765","tags":[]},{"id":"poem-c6e8a6a02770b179acc7e765","title":"卷阿","author":"佚名","dynasty":"先秦","verses":["有卷者阿，飘风自南。岂弟君子，来游来歌，以矢其音。","伴奂尔游矣，优游尔休矣。岂弟君子，俾尔弥尔性，似先公酋矣。","尔土宇昄章，亦孔之厚矣。岂弟君子，俾尔弥尔性，百神尔主矣。","尔受命长矣，茀禄尔康矣。岂弟君子，俾尔弥尔性，纯嘏尔常矣。","有冯有翼，有孝有德，以引以翼。岂弟君子，四方为则。","颙颙卬卬，如圭如璋，令闻令望。岂弟君子，四方为纲。","凤凰于飞，翙翙其羽，亦集爰止。蔼蔼王多吉士，维君子使，媚于天子。","凤凰于飞，翙翙其羽，亦傅于天。蔼蔼王多吉人，维君子命，媚于庶人。","凤凰鸣矣，于彼高冈。梧桐生矣，于彼朝阳。菶菶萋萋，雍雍喈喈。","君子之车，既庶且多。君子之马，既闲且驰。矢诗不多，维以遂歌。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-251","tags":[]},{"id":"poem-c6f17530204386efc4708b38","title":"赋得寒月寄齐已","author":"李山甫","dynasty":"唐","verses":["松下清风吹我襟，上方钟磬夜沉沉。","已知庐岳尘埃绝，更忆寒山雪月深。","高谢万缘消祖意，朗吟千首亦师心。","岂知名出徧诸夏，石上栖禅竹影侵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5ae50bb5-5d5a-4a3d-a5b3-f9f9b5321b75","tags":[]},{"id":"poem-c6f940eb583a1e1523f574b7","title":"同前换头","author":"无名氏《张协状元》","dynasty":"元","verses":["愚意：谁无祸当自遣，将息身上，没事商议。","(生)眼下里衣单又值雪，况肚中饥馁。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2513","tags":[]},{"id":"poem-c6fbeb5c062cec68aa01a602","title":"羽林骑闺人","author":"王维","dynasty":"唐","verses":["秋月临高城，城中管弦思。","离人堂上愁，稚子阶前戏。","出门复暎户，望望青丝骑。","行人过欲尽，狂夫终不至。","左右寂无言，相看共垂泪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f5c07374-f4da-464b-9ada-768ab54a26ca","tags":[]},{"id":"poem-c6fe289b0523a1b898e25e27","title":"奉和九月九日登慈恩寺浮图应制","author":"杨廉","dynasty":"唐","verses":["万乘临真境，重阳眺远空。","慈云浮鴈塔，定水映龙宫。","宝铎含飙响，仙轮带日红。","天文将瑞色，辉焕满寰中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-cdf666d1-3ed9-4732-8d0f-88d4c9752db8","tags":[]},{"id":"poem-c704c5a774cbf44b6fd68b0c","title":"马诗二十三首 十","author":"李贺","dynasty":"唐","verses":["摧榜渡乌江，神骓泣向风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f3ced668-1a31-4bfb-a688-4a21b6d20301","tags":[]},{"id":"poem-c70db8e3ac198f9dc0b058b6","title":"南园十三首 六","author":"李贺","dynasty":"唐","verses":["寻章摘句老雕虫，晓月当帘挂玉弓。","不见年年辽海上，文章何处哭秋风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-22f75e20-7e62-4c0e-93ca-f71ebba61fa6","tags":[]},{"id":"poem-c7135241475500e897016dc8","title":"和令狐补阙春日独游西街","author":"赵嘏","dynasty":"唐","verses":["左掖初辞近侍班，马嘶寻得过街闲。","映鞭柳色微遮水，随步花枝欲碍山。","暖泛鸟声来席上，醉从诗句落人间。","此时失意哀吟客，更觉风流不可攀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-86c257e7-faed-4e51-a543-9e1e16f7d3dd","tags":[]},{"id":"poem-c716269c5626fa48cc655f22","title":"渼陂西南台","author":"杜甫","dynasty":"唐","verses":["高台面苍陂，六月风日冷。","蒹葭离披去，天水相与永。","怀新目似击，接要心已领。","仿像识鲛人，空蒙辨鱼艇。","错磨终南翠，颠倒白阁影。","崷崒增光辉，乘陵惜俄顷。","劳生媿严郑，外物慕张邴。","世复轻骅骝，吾甘杂鼃黾。","知归俗可忽，取适事莫竝。","身退岂待官，老来苦便静。","况资菱芡足，庶结茅茨迥。","从此具扁舟，弥年逐清景。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3d43a429-0280-47db-a8cd-cbd9e6d3fa8b","tags":[]},{"id":"poem-c717793af7c82ce939989f93","title":"三七","author":"王梵志","dynasty":"唐","verses":["见恶须藏掩，知贤中华赞阳。","（「唯」，伯三五五八作「为」。","「阳」，项楚校作「扬」。","）但（一本作「若」。","）能依此语，秘密立身方。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7e3bc977-d2b8-4bc9-b264-e2d63f9e3e47","tags":[]},{"id":"poem-c71e383ed841fcec9f02df60","title":"邠宁春日","author":"李益","dynasty":"唐","verses":["桃李年年上国新，风沙日日塞垣人。","伤心更见庭前柳，忽有千条欲占春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-3a692edc-d3bd-4be8-8142-42e9d058030c","tags":[]},{"id":"poem-c721dd5e293ce65ed2d76f04","title":"吊灵均","author":"王鲁复","dynasty":"唐","verses":["万古汨罗深，骚人道不沈。","明明唐日月，应见楚臣心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-bd157d95-20f8-4e64-b2df-bda96308e128","tags":[]},{"id":"poem-c7326a038769942d7752aa9e","title":"河渎神·河上望丛柯","author":"温庭筠","dynasty":"唐","verses":["河上望丛柯，庙前春雨来时。","楚山无限鸟飞迟，兰棹空伤别离。","何处杜鹃啼不歇，艳红开尽如血。","蝉鬓美人愁绝，百花芳草佳节。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-44","tags":[]},{"id":"poem-c73622b52cd5afc01e62b799","title":"于中好·独背残阳上小楼","author":"纳兰性德","dynasty":"清","verses":["独背残阳上小楼，谁家玉笛韵偏幽。","一行白雁遥天暮，几点黄花满地秋。","惊节序，叹沉浮，秾华如梦水东流。","人间所事堪惆怅，莫向横塘问旧游。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-114","tags":[]},{"id":"poem-c74255fa98b9fb7d9a64336b","title":"鹧鸪天·又向荆州住半年","author":"张孝祥","dynasty":"宋","verses":["又向荆州住半年。","西风催放五湖船。","来时露菊团金颗，去日池荷叠绿钱。","斟别酒，扣离弦。","一时宾从最多贤。","今宵拼醉花迷坐，后夜相思月满川。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-242","tags":[]},{"id":"poem-c7530c58d1c3108c4b340cb0","title":"忆仙姿・如梦令·江上潮回风细","author":"贺铸","dynasty":"宋","verses":["江上潮回风细。","红袖倚楼凝睇。","天际认归舟，但见平林如荠。","迢递。","迢递。","人更远于天际。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-38","tags":[]},{"id":"poem-c759ca2d2a4746b85cc1c5a1","title":"桐江闲居作十二首 十一","author":"贯休","dynasty":"唐","verses":["忆在山中日，为僧鬓欲衰。","一灯常到晓，十载不离师。","水汲冰溪滑，钟撞雪阁危。","从来多自省，不学拟何为。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4c2b1379-b10f-401e-b172-8081c5044a01","tags":[]},{"id":"poem-c76196c4a8edb40c98bad94c","title":"杨柳枝·宜春苑外最长条","author":"温庭筠","dynasty":"唐","verses":["宜春苑外最长条，闲袅春风伴舞腰。","正是玉人肠绝处，一渠春水赤栏桥。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-29","tags":[]},{"id":"poem-c76df91668e11b441c28d19d","title":"菩萨蛮·喧喧车马西郊道","author":"陈师道","dynasty":"宋","verses":["喧喧车马西郊道。","临行更觉人情好。","住有一年情。","去留千载名。","离歌声欲尽。","只作常时听。","天上玉堂东。","阳春是梦中。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-298","tags":[]},{"id":"poem-c76e85cce2aafc3dfb96c439","title":"青门饮·胡马嘶风","author":"时彦","dynasty":"宋","verses":["胡马嘶风，汉旗翻雪，彤云又吐，一竿残照。","古木连空，乱山无数，行尽暮沙衰草。","星斗横幽馆，夜无眠、灯花空老。","雾浓香鸭，冰凝泪烛，霜天难晓。","长记晓妆才了，一杯未尽，离怀多少。","醉里秋波，梦中朝雨，都是醒时烦恼。","料有牵情处，忍思量、耳边曾道。","甚时跃马归来，认得迎门轻笑。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-65","tags":["宋词三百首"]},{"id":"poem-c76f4ce129d1a3c0f1922a60","title":"九日登望仙台呈刘明府容","author":"崔曙","dynasty":"唐","verses":["汉文皇帝有高台，此日登临曙色开。","三晋云山皆北向，二陵风雨自东来。","关门令尹谁能识，河上仙翁去不回。","且欲近寻彭泽宰，陶然共醉菊花杯。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1c1d545e-07a1-46a9-bb76-b7473c1fde43","tags":["唐诗三百首","七言律诗","写景","登高","重阳节"]},{"id":"poem-c771839f9b8a30dac915cb43","title":"九章·橘颂","author":"屈原","dynasty":"先秦","verses":["后皇嘉树，橘徕服兮。","受命不迁，生南国兮。","深固难徙，更壹志兮。","绿叶素荣，纷其可喜兮。","曾枝剡棘，圆果抟兮。","青黄杂糅，文章烂兮。","精色内白，类任道兮。","纷缊宜修，姱而不丑兮。","嗟尔幼志，有以异兮。","独立不迁，岂不可喜兮？","深固难徙，廓其无求兮。","苏世独立，横而不流兮。","闭心自慎，终不失过兮。","秉德无私，参天地兮。","愿岁并谢，与长友兮。","淑离不淫，梗其有理兮。","年岁虽少，可师长兮。","行比伯夷，置以为像兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-20","tags":[]},{"id":"poem-c792939a212700fd0874251f","title":"鹧鸪天·遍赏扬州百种花","author":"陈造","dynasty":"宋","verses":["遍赏扬州百种花。","因循忘却鬓苍华。","客闲惯刻分题烛，坐久还生醉眼霞。","催掺鼓，趁鸣笳。","未应回首问归槎。","清明寒食风烟地，判到今春不著家。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-417","tags":[]},{"id":"poem-c79660ef83fd6190bdb64394","title":"恭和御制赐太师致仕文彦博七言四韵诗一首","author":"苏颂","dynasty":"宋","verses":["出处逢时道不殊，当年功立老闲居。","来膺冕绂三公命，归奉云章五色书。","社稷元臣名已遂，山河雄镇宠仍疏。","琼林诏饯衣冠盛，岂止都门百两车。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-f36c3cf1-00b4-45ee-94dd-57ae17fd377a","tags":[]},{"id":"poem-c7a2b0538d94b477ef41bba8","title":"从驾温泉宫","author":"徐安贞","dynasty":"唐","verses":["神女调温液，年年待圣人。","试开临水殿，来洗属车尘。","暖气随明主，恩波浃近臣。","灵威自无极，从此献千春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f3b708f8-cfaa-4fad-81bd-7219ca1f10ec","tags":[]},{"id":"poem-c7a494c3473afe93c3d85161","title":"五次韵","author":"王十朋","dynasty":"宋","verses":["涪陵妃子谩名园，岂似闽南绿一盘。","最喜色同青玉案，不妨功并紫金丹。","画看红紫品流俗，诗嚼氷霜牙颊寒。","吟罢闲观右军帖，来禽青李可同餐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-44c43007-6258-41b0-8fd6-1296be9fc240","tags":[]},{"id":"poem-c7a563bbfe0101ffb11d5915","title":"送李崧老归闽二首  其二","author":"张栻","dynasty":"宋","verses":["公事妨开卷，遐征念索居。","能来数月款，端为百忧纾。","师友洛川上，人才元祐初。","归来有新益，不惜几行书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-212c4177-fd9a-4333-b13a-e0207859a786","tags":[]},{"id":"poem-c7b1f40e785317b24186b9d6","title":"满宫花·月沉沉","author":"尹鹗 六首","dynasty":"五代","verses":["月沉沉，人悄悄，一炷后庭香袅。","风流帝子不归来，满地禁花慵扫。","离恨多，相见少，何处醉迷三岛。","漏清宫树子规啼，愁锁碧窗春晓。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-29","tags":[]},{"id":"poem-c7b9a5d30907ea29c78ed5d2","title":"春日忆家","author":"李嘉祐","dynasty":"唐","verses":["自觉劳乡梦，无人见客心。","空余庭草色，日日伴愁襟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-098ed74c-c5fa-4944-9078-b76bd958fbba","tags":[]},{"id":"poem-c7c09e93f3c85f4c2cedbb7a","title":"临江仙·不见昭阳宫内柳","author":"许庭","dynasty":"宋","verses":["不见昭阳宫内柳，黄金齐拈轻柔。","东君昨夜到皇州。","玉阶金井，无处不风流。","怅望翠华春欲暮，六宫都锁春愁。","暖风吹动绣帘钩。","飞花委地，时转玉香球。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-549","tags":[]},{"id":"poem-c7c167268e9915e2708d47d1","title":"夕次盱眙县","author":"韦应物","dynasty":"唐","verses":["落帆逗淮镇，停舫临孤驿。","浩浩风起波，冥冥日沈夕。","人归山郭暗，雁下芦洲白。","独夜忆秦关，听钟未眠客。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-11424603-9a22-4564-89a4-95e1766f9685","tags":["唐诗三百首","五言古诗","写景","抒情","思乡"]},{"id":"poem-c7d1255e3ea9ceb8593eb36a","title":"忆仙姿・如梦令·彩舫解维官柳","author":"贺铸","dynasty":"宋","verses":["彩舫解维官柳。","楼上谁家红袖。","团扇弄微风，如为行人招手。","回首。","回首。","云断武陵溪口。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-51","tags":[]},{"id":"poem-c7d283b65bdd59f9cfbef816","title":"和黄漕雪中将至长沙","author":"张栻","dynasty":"宋","verses":["吾道元如砥，人间谩畏途。","未容舟溯峡，且泛雪平湖。","子孝宁投杼，天回看脱弧。","不应从我懒，欲老豆麻区。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-2071c2e2-f764-4402-aeae-f512b4b02db9","tags":[]},{"id":"poem-c7d615b11b7786d5edfeae40","title":"重阳四首 四","author":"司空图","dynasty":"唐","verses":["白发怕寒梳更懒，黄花晴日照初开。","篱头应是蝶相报，已被邻家携酒来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c0783ac9-a773-46ac-ba0b-f718010cd17e","tags":[]},{"id":"poem-c7d75f414b0a6a620f60be76","title":"得诸季书报薛克寅范茂载胡仲俨皆物故感怆有作","author":"李纲","dynasty":"宋","verses":["新故继凋丧，初非因荷戈。","波惊川阅水，霜早叶辞柯。","世上故人少，录中新鬼多。","浮生端若此，伤感意如何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-5eb29466-7d0b-429f-9eba-f7180445d4f9","tags":[]},{"id":"poem-c7dd1160286f5bf43cd669c9","title":"句  其九","author":"孟宾于","dynasty":"宋","verses":["早知落处随疏雨，悔得开时顺暖风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-8db71171-5153-49ba-8018-1a5ccb3dbecf","tags":[]},{"id":"poem-c7e8ec3d40dc034ffb9fc0a8","title":"七娘子·风剪冰花飞零乱","author":"谢逸","dynasty":"宋","verses":["风剪冰花飞零乱。","映梅梢、素影摇清浅。","绣幄寒轻，兰薰烟暖。","艳歌催得金荷卷。","游梁已觉相如倦。","忆去年、舟渡淮南岸。","别后销魂，冷猿寒雁。","角声只送黄昏怨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-649","tags":[]},{"id":"poem-c7eb8058c3dee450c369e22f","title":"诉衷情·鸳鸯交颈绣衣轻","author":"毛文锡","dynasty":"五代","verses":["鸳鸯交颈绣衣轻，碧沼藕花馨。","偎藻荇，映兰汀，和雨浴浮萍。","思妇对心惊，想边庭。何时解佩掩云屏，诉衷情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-29","tags":[]},{"id":"poem-c7f24e61dcaf93e80ac98ac9","title":"怀素上人草书歌","author":"朱逵","dynasty":"唐","verses":["几年出家通宿命，一朝却忆临池圣。","转腕摧锋增崛崎，秋毫茧纸常相随。","衡阳客舍来相访，连饮百杯神转王。","忽闻风里度飞泉，纸落纷纷如跕鸢。","形容脱略真如助，心思周游在何处。","笔下惟看激电流，字成只畏盘龙去。","怪状崩腾若转蓬，飞丝历乱如回风。","长松老死倚云壁，蹙浪相翻惊海鸿。","于今年少尚如此，历覩远代无伦比。","妙绝当动鬼神泣，崔蔡幽魂更心死。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2365ddee-8124-44e2-ac84-53e8c677b8a9","tags":[]},{"id":"poem-c7f39738e3c9175b00b0d778","title":"和定国湖上  其一","author":"刘跂","dynasty":"宋","verses":["溪光涵影碧萧萧，四合深林不见梢。","寒暑若言无避处，世间那有况云巢。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-fb4aafb2-087a-417c-a957-dd8416a6b2c9","tags":[]},{"id":"poem-c7f8ffd2bc4c40f385c8aaeb","title":"千叶桃花","author":"杨凭","dynasty":"唐","verses":["千叶桃花胜百花，孤荣春晚驻年华。","若教避俗秦人见，知向河源旧侣夸。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-08d0e076-ff46-4c75-b7d2-60a94290dfb6","tags":[]},{"id":"poem-c7fb2c4a19c3e42ce1f816b8","title":"扬之水","author":"佚名","dynasty":"先秦","verses":["扬之水，不流束楚。终鲜兄弟，维予与女。无信人之言，人实诳女。","扬之水，不流束薪。终鲜兄弟，维予二人。无信人之言，人实不信。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-91","tags":[]},{"id":"poem-c8091e8d39b60ca5c634b687","title":"坏屋","author":"王建","dynasty":"唐","verses":["官家有坏屋，居者愿离得。","苟或幸其迁，回循任倾侧。","若当君子住，一日还修餙。","必使换榱楹，先须木端直。","永令雀与鼠，无处求栖息。","坚固传后人，从今勉劳力。","以兹喩臣下，亦可成邦国。","虽曰愚者词，将来幸无惑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-380d7f3c-cd6c-47ce-9ccb-a8a90906376f","tags":[]},{"id":"poem-c80bd6e7466a4694eca9f213","title":"销金帐","author":"施惠《幽闺记》","dynasty":"元","verses":["(老旦)黄昏悄悄，助冷风儿起。","想今朝，思向日，曾对这般时节，这般天气。","羊羔美酒，美酒销金帐里。","兵乱人慌，远远离乡里。","如今怎生，怎生街头上睡？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3025","tags":[]},{"id":"poem-c811426f1784d504343a4dbb","title":"临江仙·深秋寒夜银河静","author":"尹鹗 六首","dynasty":"五代","verses":["深秋寒夜银河静，月明深院中庭。","西窗幽梦等闲成，逡巡觉后，特地恨难平。","红烛半消残焰短，依稀暗背银屏。","枕前何事最伤情，梧桐叶上，点点露珠零。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-28","tags":[]},{"id":"poem-c81360d86203945ccdad13c7","title":"和史侍郎游澹岩韵六首  其一","author":"曾协","dynasty":"宋","verses":["底叹兹岩省见稀，惯居故国看山围。","应缘此日慰岑寂，聊遣清诗为发挥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1daf2b98-bc63-41ef-9b66-7b4098ea3758","tags":[]},{"id":"poem-c82cfb8260256330faef0c32","title":"九思·悯上","author":"王逸","dynasty":"汉","verses":["哀世兮睩睩，𬣡𬣡兮嗌喔。","众多兮阿媚，骪靡兮成俗。","贪枉兮党比，贞良兮茕独。","鹄窜兮枳棘，鹈集兮帷幄。","罽蕠兮青葱，槁本兮萎落。","睹斯兮伪惑，心为兮隔错。","逡巡兮圃薮，率彼兮畛陌。","川谷兮渊渊，山阜兮峉峉。","丛林兮崟崟，株榛兮岳岳。","霜雪兮漼溰，冰冻兮洛泽。","东西兮南北，罔所兮归薄。","庇荫兮枯树，匍匐兮岩石。","蜷跼兮寒局数，独处兮志不申。","年齿尽兮命迫促，魁垒挤摧兮常困辱。","含忧强老兮愁无乐，须发苎悴兮顠鬓白。","思灵泽兮一膏沐，怀兰英兮把琼若，待天明兮立踯躅。","云蒙蒙兮电鯈烁，孤雌惊兮鸣呴呴。","思怫郁兮肝切剥，忿悁悒兮孰诉告。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-59","tags":[]},{"id":"poem-c82ebf574b278e1033f6baba","title":"无题","author":"张籍","dynasty":"唐","verses":["桃溪柳陌好经过，灯下妆成月下歌。","为是襄王故宫地，至今犹有细腰多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-dc2356f0-cb33-4b72-8cd1-6d45df9976a3","tags":[]},{"id":"poem-c82f5975348eef0edb3afcad","title":"和贾舍人早朝","author":"王维","dynasty":"唐","verses":["绛帻鸡人报晓筹，尚衣方进翠云裘。","九天阊阖开宫殿，万国衣冠拜冕旒。","日色才临仙掌动，香烟欲傍衮龙浮。","朝罢须裁五色诏，佩声归到凤池头。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-和賈舍人早朝","tags":[]},{"id":"poem-c82ff10b42ffa26a85b0dddf","title":"送越客归","author":"刘得仁","dynasty":"唐","verses":["霜薄东南地，江枫落未齐。","众山离楚上，孤棹宿吴西。","渚客留僧语，笼猨失子啼。","到家冬即是，荷尽若耶溪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-def9ba93-b443-4807-8332-97c615a371c2","tags":[]},{"id":"poem-c83445cce37fc1a8f92045b5","title":"哭相思","author":"施惠《幽闺记》","dynasty":"元","verses":["(生、小旦)兄妹当初两分散，谁知此地重相见？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3110","tags":[]},{"id":"poem-c8369e4524c912f5c2f0003e","title":"秋壑","author":"释居简","dynasty":"宋","verses":["泠风在怀袖，何必借商弦。","就下识天巧，适安忘地偏。","寒泓嫌雪暖，秋草似春鲜。","见说蓬莱远，依稀拄杖前。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-7fe4767e-92ea-4d74-84a3-7e64a397de3c","tags":[]},{"id":"poem-c84521c95338204f7959ef2d","title":"好事近·手种满阑花","author":"张镃","dynasty":"宋","verses":["手种满阑花，瑞露一枝先坼。","拄个杖儿来看，两三人门客。","今朝欢笑且衔杯，休更问明日。","此意悠然谁会，有湖边风月。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-339","tags":[]},{"id":"poem-c84c04a5c2b455d0d89919a5","title":"偈颂（幷序○序为南岳齐己撰） 十六","author":"居遁","dynasty":"唐","verses":["人若无心称道情，觑见（《祖堂集》卷八作「识得」）无明道已明。","人能弘道道能显，道在人中人自宁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-228fef27-ae89-4cc6-9ef9-bef76a4b1948","tags":["衡山"]},{"id":"poem-c84e2ee7f47dc7ebd123a546","title":"送应之道人归江西","author":"徐铉","dynasty":"宋","verses":["曾骑竹马傍洪涯，二十余年变物华。","客梦等闲过驿阁，归帆遥羡指龙沙。","名题小篆矜垂露，诗作吴吟对绮霞。","岁暮定知回未得，信来凭为寄梅花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2ccdd781-3e3d-4ee6-9098-94c436403823","tags":[]},{"id":"poem-c856d63edab68a7663623faf","title":"郊庙歌辞 周朝飨乐章 福顺","author":"不详","dynasty":"唐","verses":["圣皇端拱，多士输忠。","蛮觞共献，臣心毕同。","声齐嵩岳，祝比华封。","千龄万祀，常保时雍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-64afb35e-d5b9-4f5b-af6b-1b47a72d1e9e","tags":[]},{"id":"poem-c85929dbabf8cd7aec560f13","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["是我夫，不相认，见着我忙闭了门。","我当初闭门不留伊，你及第应是无分。","千余里，到此来，望你厮存问。","目下要归我没盘缠，我今宵，更无投奔。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2657","tags":[]},{"id":"poem-c85f197328a4adb842a7fa7b","title":"点绛唇·露下风高","author":"晏殊","dynasty":"宋","verses":["露下风高，井梧宫簟生秋意。","画堂筵启。","一曲呈珠缀。","天外行云，欲去凝香袂。","炉烟起。","断肠声里。","敛尽双蛾翠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-451","tags":[]},{"id":"poem-c868dfbe65d78836e06aced9","title":"扬州作","author":"米芾","dynasty":"宋","verses":["春风何索寞，带雪入扬州。","尚想遗钗雀，曾观上玉钩。","真同一梦觉，坐想十年游。","邂逅逢孙楚，酣歌慰滞留。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-5d42805a-9525-40fe-9e2b-c7ff8469e255","tags":[]},{"id":"poem-c86c01061b0bea486bd96652","title":"南乡子·相见处","author":"李珣","dynasty":"五代","verses":["相见处，晚晴天，斜桐花下越台前。","暗里回眸深属意，遗双翠，骑象背人先过水。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-34","tags":[]},{"id":"poem-c86f3d1e10706ab4a52d3e48","title":"春秋战国门 张孟谭","author":"周昙","dynasty":"唐","verses":["强兵四合国将危，赖有谋臣为发挥。","城内蒿铜诚自有，无谋谁解见玄机。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6cc8da6d-32b2-4096-a7b1-807ca4933af6","tags":[]},{"id":"poem-c87a540e00d42fe2de47b658","title":"踏莎行·衾凤犹温","author":"张先","dynasty":"宋","verses":["衾凤犹温，笼鹦尚睡。","宿妆稀淡眉成字。","映花避月上行廊，珠裙折折轻垂地。","翠幕成波，新荷贴水。","纷纷烟柳低还起。","重墙绕院更重门，春风无路通深意。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-270","tags":[]},{"id":"poem-c8818f153bd14886b48ceb47","title":"景德寺饮会丘思同作述怀诗兼纪一席之事见约同赋辄次元韵","author":"苏颂","dynasty":"宋","verses":["濒江多胜宇，兹地更推高。","结友为文会，开樽较饮豪。","春华今始盛，圣代况亲遭。","美景堪行乐，雄谈任叫号。","数家供法馔，百斝和春醪。","异味频登俎，良庖旋奏刀。","盘丰介象鲙，手马毕生螯。","极量觚并榼，忘形甖与槽。","怜君皆旷达，独我叹徒劳。","俗状区区外，刚肠渐渐熬。","壮心虽不屈，谗口亦奚逃。","感寓尝怀古，愁来几悼骚。","宦涂蜗斗角，世事猬森毛。","自得犹千虑，谁能挫一毫。","无烦恶蝇点，须拟效龙韬。","暂适惟诗酒，难兼是燕敖。","纵欢忘倦厌，论契甚坚牢。","峻节凌修干，清风遏怒涛。","就贤知不倦，营道岂云叨。","此席今谁继，知音尽俊髦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-c6ada7af-b632-4753-a0a2-0cbd6ea05d9f","tags":[]},{"id":"poem-c890f97b12073c650ecb5fc2","title":"和陈承事喜雨应祈见贺","author":"华镇","dynasty":"宋","verses":["空阶昨夜响淋漓，正是东皋渴雨时。","蝼蚁未应能有感，乾坤自是本无私。","已知协气通三壤，想见嘉禾秀两岐。","更待秋冬高廪后，与君同赋誉尧诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-f2ccf839-11ac-4030-99c9-1e13ed923eef","tags":[]},{"id":"poem-c89a6bb9ba7d05d940a52d9d","title":"嘲燕","author":"宋伯仁","dynasty":"宋","verses":["年来乳燕亦堪羞，不学杨花得自由。","飞过几家门户去，直须寻见最高楼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-0811d637-5bc5-4469-b336-dc2d93c972e5","tags":[]},{"id":"poem-c89a9c25eb91e98ff503821d","title":"秋日江居闲咏","author":"卿云","dynasty":"唐","verses":["寄居江岛边，闲咏见秋残。","草白牛羊瘦，风高猨鸟寒。","检方医故疾，挑荠备中餐。","时复停书卷，鉏莎种木兰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2b492836-6c41-44e0-bdcd-4688fd62e9f1","tags":[]},{"id":"poem-c8a2067876e45a23e3555845","title":"桐柏观","author":"任翻","dynasty":"唐","verses":["飘飘云外者，𫏐宿聚仙堂。","半夜人无语，中宵月送凉。","鹤归高树静，萤过小池光。","不得多时住，门开是事忙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-78c6e097-b066-4e41-bec8-341110b60443","tags":[]},{"id":"poem-c8a6626c5b17c5bacc7277bd","title":"蜉蝣","author":"佚名","dynasty":"先秦","verses":["蜉蝣之羽，衣裳楚楚。心之忧矣，于我归处。","蜉蝣之翼，采采衣服。心之忧矣，于我归息。","蜉蝣掘阅，麻衣如雪。心之忧矣，于我归说。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-149","tags":[]},{"id":"poem-c8a7613983a79adfe507fc6a","title":"卜算子·临镜笑春风","author":"向子𬤇","dynasty":"宋","verses":["临镜笑春风，生怕梅花妒。","疑是西湖处士家，疏影横斜处。","江静竹娟娟，绿绕青无数。","独许幽人子细看，全胜墙东路。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-169","tags":["西湖"]},{"id":"poem-c8b2e18e7328772194327e96","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［老旦］蒙错爱，为眷属，这恩德深铭肺腑。","奈缘艰苦，迤逦不能勾参岳父。","到如今又蒙相呼，顿教娘心中犹豫。","试问我孩儿媳妇，怎生区处？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8117","tags":[]},{"id":"poem-c8ba1e3933948fe35d787ddb","title":"五供养","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)别来久矣，自离朝尊体无恙。","骨肉重再睹，喜非常。","(外)孩儿，屈指数月，折倒尽昔时模样。","思故里，念家乡，多少鬓边霜。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3003","tags":[]},{"id":"poem-c8c4272310a5dde5f4ad46f1","title":"诗三首  其二","author":"释遇贤","dynasty":"宋","verses":["心闲增道气，忍事敌灾屯。","谨言终少祸，节俭胜求人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-cebea315-5618-405d-86ee-5a294fb18f81","tags":[]},{"id":"poem-c8d06657ac0782276a790316","title":"登历下古城员外新亭二首  其二","author":"王秬","dynasty":"宋","verses":["吾宗固神秀，体物写谋长。","形制开古迹，曾冰延乐方。","太山雄地理，巨壑眇云庄。","高兴泊烦促，永怀清典常。","含弘知四大，出入见三光。","负郭喜粳稻，安时歌吉祥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-21d686dd-1cae-4b73-b147-461ee7b3c660","tags":[]},{"id":"poem-c8d6f40ab466212ed626d5b0","title":"望江南・忆江南·柯山瑞","author":"廖刚","dynasty":"宋","verses":["柯山瑞，云路玉桥横。","六月天香琼蕊秀，千年人瑞昂星明。","风露湿麒麟。","廊庙器，冰雪照精神。","妙世文章凌贾马，致君事业富姬衡。","松桧倚青青。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-950","tags":[]},{"id":"poem-c8ef8ad4d39724962d56f77e","title":"宫怨","author":"李益","dynasty":"唐","verses":["露湿晴花春殿香，月明歌吹在昭阳。","似将海水添宫漏，共滴长门一夜长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-3ba7240c-f2c7-47b2-aab4-df61036655ca","tags":["闺怨"]},{"id":"poem-c8f44d1d6fc3cce4753d0a83","title":"爱笋","author":"陈造","dynasty":"宋","verses":["犀非犀，玉非玉，拂拂轻霜浮脆绿。","披箨含梢欲成竹，娟娟褭褭森可束。","稀间只称佳月照，劲处差耐清风触。","少忍充庖得补林，主人为目不为腹。","论材似也子胜人，终竟鼻祖与膏馥。","官闲尽日据胡床，乐与此君同避俗。","冷笑京华痴少年，枉费千金买花木。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a09f28db-ddfa-4990-86e7-a92726aa224b","tags":[]},{"id":"poem-c8f4a63d8ac96b0f5b154f75","title":"棫朴","author":"佚名","dynasty":"先秦","verses":["芃芃棫朴，薪之槱之。济济辟王，左右趣之。","济济辟王，左右奉璋。奉璋峨峨，髦士攸宜。","淠彼泾舟，烝徒楫之。周王于迈，六师及之。","倬彼云汉，为章于天。周王寿考，遐不作人？","追琢其章，金玉其相。勉勉我王，纲纪四方。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-237","tags":[]},{"id":"poem-c8fcb85730b06b8a04ee8e52","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦)自从爹爹死了，止有嫡亲兄嫂。","他缘何反面生嗔？拆散大妻两口。","望叔叔做主，望叔叔做主。","想是姻缘不到，怎得大妻谐老？自今朝，拜别分离去，交奴苦怎熬？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8879","tags":[]},{"id":"poem-c90dd07d09612a550726b4b3","title":"示师文","author":"陈造","dynasty":"宋","verses":["朴樕已非材，肮脏遽成翁。","生无适时具，何向不涂穷。","頼结文字缘，人士饱过从。","三年尉山邑，趣操有同风。","博古得二臧，秀发仍两钟。","蒋侯厚本学，落笔语更工。","我卜当涂居，薪米耐阙供。","从渠得琢磨，遗汝不己丰。","士生在知道，寡陋难言功。","会理贵博观，受物由虚中。","潢污不扬漪，大江日倾东。","迟汝草灵光，一觞寿乃公。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-e94c8af6-8264-44c7-a908-97698a4b8a51","tags":[]},{"id":"poem-c912dc67493a438d45883d83","title":"招隐士","author":"淮南小山","dynasty":"汉","verses":["桂树丛生兮山之幽，偃蹇连蜷兮枝相缭。","山气巄嵷兮石嵯峨，溪谷崭岩兮水曾波。","猿狖群啸兮虎豹嗥，攀援桂枝兮聊淹留。","王孙游兮不归，春草生兮萋萋。","岁暮兮不自聊，蟪蛄鸣兮啾啾。","坱兮轧，山曲岪，心淹留兮恫慌忽。","罔兮沕，憭兮栗，虎豹穴。","丛薄深林兮，人上栗。","嵚岑埼礒兮，碅磳磈硊。","树轮相纠兮，林木茷骫。","青莎杂树兮，薠草靃靡。","白鹿麏麚兮，或腾或倚。","状貌崟崟兮峨峨，凄凄兮漇漇。","猕猴兮熊罴，慕类兮以悲。","攀援桂枝兮聊淹留。","虎豹斗兮熊罴咆，禽兽骇兮亡其曹。","王孙兮归来，山中兮不可以久留。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-29","tags":[]},{"id":"poem-c91e45d1dde27c0251269b4a","title":"水调歌头·秋杪暑方退","author":"李纲","dynasty":"宋","verses":["秋杪暑方退，清若玉壶冰。","高楼对月，天上宫殿不曾扃。","散下凄然风露，影照江山如昼，浑觉俗缘轻。","弋者欲何慕，鸿羽正冥冥。","世间法，唯此事，最堪凭。","太虚心量，聊假梨枣制颓龄。","但使心安身健，静看草根泉际，吟蚓与飞萤。","一坐小千劫，无念契无生。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-559","tags":[]},{"id":"poem-c9307ffc9e3752edae8cbeb3","title":"诉衷情·花阴柳影映帘栊","author":"毛滂","dynasty":"宋","verses":["花阴柳影映帘栊。","罗幕绣重重。","行云自随语燕，回雪趁惊鸿。","银字歇，玉杯空。","蕙烟中。","桃花髻暖，杏叶眉弯，一片春风。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-797","tags":[]},{"id":"poem-c93b9ce9794412d3bc0f0cb8","title":"送人随姊夫任云安令","author":"刘言史","dynasty":"唐","verses":["闲逐维私向武城，北风青雀片时行。","孤帆瞥过荆州岸，认得瞿塘急浪声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-327e2367-7dab-4ab9-96b1-8a357b515b1e","tags":[]},{"id":"poem-c93d78cf45af0c05c59b78fa","title":"喜到竹斋书事呈无位居士","author":"林敏修","dynasty":"宋","verses":["岭上小梅初破萼，同云作寒雪花落。","千里南还喜见君，一杯相属宁辞数。","楚狂小子笑孔丘，杖屦谩学名山游。","二年胜景览欲尽，赢得颜发先惊秋。","却归竹下寻诗句，追讲前欢秃千兔。","竹间已有嗣宗狂，吟醉何妨陪杖屦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-3f8dc26d-e44c-498e-ae45-c86818619bc6","tags":[]},{"id":"poem-c93e6d86","title":"明日歌","author":"钱福","dynasty":"明","verses":["明日复明日，明日何其多。","我生待明日，万事成蹉跎。","世人若被明日累，春去秋来老将至。","朝看水东流，暮看日西坠。","百年明日能几何？请君听我明日歌。"],"enabled":true,"collection":"历代名篇","source":"钱福《鹤滩稿》诗《明日歌》，采用“我生待明日”通行本。","tags":["惜时"]},{"id":"poem-c9423d9ad91cfab67dcc0a72","title":"调笑・调笑令·相误","author":"晁补之","dynasty":"宋","verses":["相误。","空凝伫。","郑子江头逢二女。","霞衣曳玉非尘土。","笑解明珰轻付。","月从云堕劳相慕。","自有骖鸾仙侣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-282","tags":[]},{"id":"poem-c94526baa90430cc34f1ccac","title":"和主司王起","author":"孟守","dynasty":"唐","verses":["科文又主守初时，光显门生济会期。","美擅东堂登甲乙，荣同内署侍恩私。","群莺共喜新迁木，双凤皆当即入池。","别有倍深知感士，曾经两度得芳枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-922c39a1-9e9c-4353-b82c-ce2cf1dd11ec","tags":[]},{"id":"poem-c954730cb99c9d86dd85da9b","title":"郊庙歌辞 周宗庙乐舞辞 明德舞","author":"不详","dynasty":"唐","verses":["惟彼岐阳，德大流光。","载造周室，泽及遐荒。","于铄圣祖，上帝是皇。","迺圣迺神，知微知彰。","新庙奕奕，丰年穰穰。","取彼血膋，以往蒸尝。","黍稷惟馨，笾豆大房。","工祝致告，受福无疆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ef905ab2-4dae-4b94-9295-1d10156acfaf","tags":[]},{"id":"poem-c95a6ac7715908f85d78bf46","title":"醉时歌","author":"杜甫","dynasty":"唐","verses":["诸公衮衮登台省，广文先生官独冷。","甲第纷纷厌粱肉，广文先生饭不足。","先生有道出羲皇，先生有才过屈宋。","德尊一代常𫐘轲，名垂万古知何用。","杜陵野客人更嗤，被褐短窄鬓如丝。","日籴太仓五升米，时赴郑老同襟期。","得钱即相觅，沽酒不复疑。","忘形到尔汝，痛饮真吾师。","清夜沈沈动春酌，灯前细雨檐花落。","但觉高歌有鬼神，焉知饿死填沟壑。","相如逸才亲涤器，子云识字终投阁。","先生早赋归去来，石田茅屋荒苍苔。","儒术于我何有哉，孔丘盗跖俱尘埃。","不须闻此意惨怆，生前相遇且衔杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-22ec1415-85ee-4aa1-8838-62aa3c9b66dd","tags":[]},{"id":"poem-c95cec75515be496838103b7","title":"次东坡月夜理髪","author":"李纲","dynasty":"宋","verses":["月明星稀乌鹊翻，先生夜起临幽轩。","呼童具栉不停手，一气溯流天地根。","自经忧患髪如葆，欲论此心无与言。","不如缄默度余日，怅望吴越空销魂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-867fd136-384d-4e57-bbdc-7be587b53dcb","tags":[]},{"id":"poem-c973b3a2eb855bf9295050f2","title":"送丁道士归南中","author":"谭用之","dynasty":"宋","verses":["孤云无定鹤辞巢，自负焦桐不说劳。","服药几年期碧落，验符何处呪丹毫。","子陵山晓红云密，青草湖平雪浪高。","从此人稀见踪迹，还应选地种仙桃。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-dc67a3e6-c1f7-483b-a56e-bb68187d1ca9","tags":[]},{"id":"poem-c97e66d0a295da8a1e092d9f","title":"阮郎归·碧溪风动满文漪","author":"米友仁","dynasty":"宋","verses":["碧溪风动满文漪。","雨馀山更奇。","淡烟横处柳行低。","鸳鸯来去飞。","人似玉，醉如泥。","一枝随鬓猗。","夷犹双桨月平西。","幽寻归路迷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-59","tags":[]},{"id":"poem-c9839ffe6b442f2cc31969df","title":"小游仙诗九十八首 六十五","author":"曹唐","dynasty":"唐","verses":["水满桑田白日沈，冻云干霰湿重阴。","辽东归客闲相过，因话尧年雪更深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-4fdecc70-5ff0-42ca-a338-b734e13a8829","tags":[]},{"id":"poem-c9879e591879e216b7302807","title":"木兰花・玉楼春·翦裁用尽春工意","author":"柳永","dynasty":"宋","verses":["翦裁用尽春工意。","浅蘸朝霞千万蕊。","天然淡泞好精神，洗尽严妆方见媚。","风亭月榭闲相倚。","紫玉枝梢红蜡蒂。","假饶花落未消愁，煮酒杯盘催结子。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-243","tags":[]},{"id":"poem-c98b51d88278fee852be9c5a","title":"好事近·风细晚轩凉","author":"洪适","dynasty":"宋","verses":["风细晚轩凉，妙句初挥新墨。","绿水池中宾佐，对嫩荷擎绿。","坐看微月上云头，清臂映寒玉。","只恐朝来酒醒，有文书羁束。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-672","tags":[]},{"id":"poem-c991f1123f749bf757a91a57","title":"柳梢青·雨过风微","author":"曾觌","dynasty":"宋","verses":["雨过风微。","温泉浴倦，妃子妆迟。","翠袖牵云，朱唇得酒，脸晕胭脂。","年年海燕新归。","怎奈向、黄昏恁时。","倚遍琼干，烧残银烛，花又争知。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-422","tags":[]},{"id":"poem-c99a2719bf5da828da932097","title":"赋得还山吟送沈四山人","author":"高适","dynasty":"唐","verses":["还山吟，天高日暮寒山深。","送君还山识君心，人生老大须恣意。","看君解作一生事，山间偃仰无不至。","石泉淙淙若风雨，桂花松子常满地。","卖药囊中应有钱，还山服药又长年。","白云劝尽桮中物，明月相随何处眠。","眠时忆问醒时事，梦魂可以相周旋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-03ca699d-7447-498d-8251-cf9f85deae11","tags":["赠别","写人","友人","赞美","写人诗"]},{"id":"poem-c9a312e6f1b0e3686385186a","title":"寄晁以道","author":"刘跂","dynasty":"宋","verses":["江东野老羹莼丝，弗羡肉山酒为池。","啖我故人吏未归，脚靴手板方苦饥。","岂无盘飧置璧圭，我乏是物君非宜。","近闻示病作居士，不似齐州称主司。","岁恶无乃馋所为，自是不当食肉糜。","书来中有七字诗，问讯劳苦开人眉。","墨丸不减官隃麋，著书寂寞来孔时。","我曹老矣善自持，莫拟狂瘦胜痴肥。","他乡异县久别离，明月千里长相思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e7b80956-5ef9-4ccd-bf9c-5426f507441f","tags":[]},{"id":"poem-c9a89afa1b69e2ad8e419f2f","title":"伤故人歌妓","author":"长孙佐辅","dynasty":"唐","verses":["愁脸无红衣满尘，万家门户不容身。","曾将一笑君前去，悮杀几多回顾人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e0cfc3de-c236-4904-aca1-f3c8536c5e17","tags":[]},{"id":"poem-c9ab183a8f001f789026b27e","title":"章台夜思","author":"韦庄","dynasty":"唐","verses":["清瑟怨遥夜，遶弦风雨哀。","孤灯闻楚角，残月下章台。","芳草已云暮，故人殊未来。","乡书不可寄，秋雁又南回。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-19796737-ec7b-4c33-8df4-a81a7ca2cc10","tags":["唐诗三百首","怀人","思乡","五言律诗"]},{"id":"poem-c9ad9e7fd35ec78ca9f1311b","title":"偈颂十四首  其七","author":"释印肃","dynasty":"宋","verses":["君不见烂柯仙，一局知他几度年。","自出洞来谁作对，未曾学手早赢先。","高不高，玄不玄，默然轻转不能言。","得失都卢无个事，一时收拾华堂前。","若人要问消息，落落真风印碧天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-713f7249-c8c4-4c7a-81f7-845cf5d831fa","tags":[]},{"id":"poem-c9aed29d38392347d2aca17c","title":"无题四首 二","author":"李商隐","dynasty":"唐","verses":["飒飒东风细雨来，芙蓉塘外有轻雷。","金蟾啮鏁烧香入，玉虎牵丝汲井回。","贾氏窥帘韩掾少，宓妃留枕魏王才。","春心莫共花争发，一寸相思一寸灰。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-811a5f9e-0df5-46f1-a587-0d4df7bca5a0","tags":["唐诗三百首","相思","女子","爱情","七言律诗"]},{"id":"poem-c9af65e58f1deb9c132c9995","title":"题清远峡观音院二首 一","author":"卢肇","dynasty":"唐","verses":["清潭洞澈深千丈，危岫攀萝上几层。","秋尽更无黄叶树，夜阑唯对白头僧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-924eca61-cda9-41c2-bcd7-18aaae35802d","tags":[]},{"id":"poem-c9c066da23fb7805f542cc14","title":"浣溪沙·燕垒空梁画壁寒","author":"纳兰性德","dynasty":"清","verses":["燕垒空梁画壁寒，诸天花雨散幽关。","篆香清梵有无间。","蛱蝶乍从帘影度，樱桃半是鸟街残。","此时相对一忘言。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-146","tags":[]},{"id":"poem-c9c4e951d67bc0616cf59caa","title":"送安法师","author":"张籍","dynasty":"唐","verses":["出郭见落日，别君临古津。","远程无野寺，宿处问何人。","原色不分路，锡声遥隔尘。","山阴到家节，犹及蕙兰春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-587eaf17-f792-45bd-a6b6-6d843d0da11e","tags":[]},{"id":"poem-c9c8751caeddd1dcc841e948","title":"浣溪沙·花信催春入帝关","author":"沈与求","dynasty":"宋","verses":["花信催春入帝关。","玉霙争腊去留间。","不禁风力又吹残。","客舍不眠清夜冷，萦愁一缕袅旃檀。","空庭月落斗栏干。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-817","tags":[]},{"id":"poem-c9dd086c92b000224797daa3","title":"寄海峤丈人","author":"徐凝","dynasty":"唐","verses":["万丈只愁沧海浅，一身谁测岁华遥。","自言来此云边住，曾看秦王树石桥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ae58f860-dc11-42d4-8654-ca8c355a3434","tags":[]},{"id":"poem-c9ed416eaa712d55155d94fd","title":"送谏议十六叔至孝义渡后奉寄","author":"孟郊","dynasty":"唐","verses":["晓渡明镜中，霞衣相飘飖。","浪凫惊亦双，蓬客将谁僚。","别饮孤易醒，离忧壮难销。","文清虽无敌，儒贵不敢骄。","江吏捧紫泥，海旗剪红蕉。","分明太守礼，跨蹑毗陵桥。","伊洛去未回，遐瞩空寂寥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2e6bfc9a-9e1a-42e6-bf59-89566c0b1932","tags":[]},{"id":"poem-c9f1b4b7c44296ccab7b76fb","title":"虞美人·晓莺啼破相思梦","author":"顾敻","dynasty":"五代","verses":["晓莺啼破相思梦，帘看金泥凤。","宿妆犹在酒初醒，翠翘慵整倚云屏，转娉婷。","香檀细画侵桃脸，罗袂轻轻敛。","佳期堪恨再难寻，绿芜满院柳成阴，负春心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-33","tags":[]},{"id":"poem-c9f42690c521da71d99badcf","title":"送法镜上人归上元","author":"张祜","dynasty":"唐","verses":["南国僧游二十年，却因无任访生缘。","风回建业秋归寺，月满秦淮夜到舡。","故老尽成双鬓雪，旧房深鏁一林烟。","莫言了悟为真理，不叹兴亡在眼前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0cf0328d-fc5c-4b83-98a2-00baca29b3bb","tags":[]},{"id":"poem-c9fc2706e663b4bd8419361e","title":"苏州江岸留别乐天","author":"张籍","dynasty":"唐","verses":["银泥裙暎锦障泥，画舸停桡马簇蹄。","清管曲终鹦鹉语，红旗影动薄寒嘶。","渐消酒色朱颜浅，欲话离情翠黛低。","莫忘使君吟咏处，女坟湖北武丘西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3db0db09-2db6-4884-bc07-4dd85d45b67c","tags":[]},{"id":"poem-c9ff9ef43ecd247395cc4cb6","title":"寄令狐郎中","author":"李商隐","dynasty":"唐","verses":["嵩云秦树久离居，双鲤迢迢一纸书。","休问梁园旧宾客，茂陵秋雨病相如。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-fb376b71-91c6-44ee-b2e4-40f5b3f71b8f","tags":["唐诗三百首","思念","写景","七言绝句","友情"]},{"id":"poem-ca113e1b18338ae8ad08a3a9","title":"寻隐者不遇","author":"贾岛","dynasty":"唐","verses":["松下问童子，言师采药去。","只在此山中，云深不知处。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4f6575cc-12cc-4986-8bfc-5cedac7bb68f","tags":["五言绝句","写人","寻访","唐诗三百首"]},{"id":"poem-ca25bb74cd386adc3218cb45","title":"阙题","author":"刘眘虚","dynasty":"唐","verses":["道由白云尽，春与青溪长。","时有落花至，远随流水香。","闲门向山路，深柳读书堂。","幽映每白日，清辉照衣裳。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a2b4fe60-9809-422d-afa7-143a2088f045","tags":["唐诗三百首","春天","写景","五言律诗"]},{"id":"poem-ca2b135980163d3e58494208","title":"咏黄莺","author":"孙处玄","dynasty":"唐","verses":["欲啭声犹涩，将飞羽未调。","高风不借便，何处得迁乔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6fc9de56-4aca-4cbb-8abe-4cfcdb96d3a6","tags":[]},{"id":"poem-ca36e42d6cbe87ecbd91935a","title":"浣溪沙·蕙炷犹熏百和秾","author":"毛滂","dynasty":"宋","verses":["蕙炷犹熏百和秾。","兰膏正烂五枝红。","风流云散太匆匆。","仙草已添君胜爽，醉乡肯为我从容。","剩风残月小庭空。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-743","tags":[]},{"id":"poem-ca37146606ec8959d4deb82f","title":"远别离","author":"张籍","dynasty":"唐","verses":["莲叶团团杏花拆，长江鲤鱼鬐鬣赤。","念君少年弃亲戚，千里万里独为客。","谁言远别心不易，天星坠地能为石。","几时断得城南陌，勿使居人有行役。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f8df321b-96ae-4faa-8e6e-c1cce6bd3e07","tags":["长江"]},{"id":"poem-ca444b41b688f9506c89158e","title":"偈颂（幷序○序为南岳齐己撰） 四十一","author":"居遁","dynasty":"唐","verses":["一室一床居物外，一瓶一钵寄生涯。","门前纵有通村路，是我何曾识一家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d2a30d72-90cf-4436-9c2d-f53d11494bfe","tags":["衡山"]},{"id":"poem-ca484b82f51ff944c8b92a2d","title":"·","author":"慧救","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-817738bb-72ff-490a-bafa-f61445b104eb","tags":[]},{"id":"poem-ca4cc92c328455c84b1e1457","title":"荅卢邺","author":"良乂","dynasty":"唐","verses":["风泉秪向梦中闻，身外无余可寄君。","当户一轮惟晓月，挂簷数片是秋云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-bb3a71a3-2c27-40d6-a58a-a0753f145b75","tags":[]},{"id":"poem-ca4f6accf9cbb7a3cefb1dcb","title":"村庄即事","author":"宋伯仁","dynasty":"宋","verses":["青旗猎猎又村庄，僊景还他是水乡。","人近七旬头未白，山无重数叶初黄。","稻畦明月家家酒，茅屋清歌处处霜。","满地菊花秋欲老，客怀牢落愧重阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-881ef0b4-3e06-415b-b640-cb8ea65c90ce","tags":[]},{"id":"poem-ca54359988a23395e95c2e86","title":"闻知己入翰林","author":"贯休","dynasty":"唐","verses":["天骥头似鸟，[倐]忽四天下。","南金色如椹，入火不见火。","吾交二名士，遽立于帝左。","凤姿既出世，天意嘱在我。","奇哉子渊颂，无可无不可。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6d5fecfd-f432-4fa6-8f77-3aee61fd3317","tags":[]},{"id":"poem-ca56d18f6ef4fba0bf2c9ce9","title":"硖石山","author":"杨氏","dynasty":"唐","verses":["此山霭霭通云烟，峭壁嵯峨势分绵。","丹水流衍曲如带，风皱罗纹听管弦。","莺啼花开入禅意，掷笔台前梵呗宣。","遥想当年无遮会，纷纷散落雨花天。","（见《山右金石记》。","）（〖1〗《山右金石记》卷九《硖石山杨夫人摩崖诗刻》条引《鳯台县志》：石壁刻『唐天佑丙子岁六月十四日离府，至中旬巡祀到此，登陟硖石山，偶上先师掷笔台，眺观景象，为诗上碣。","弘农郡君夫人述。","』按天佑丙子，晋称天佑十一年〖望按：丙子，当是晋天祐十三年，公元九一六年〗。","是年，李嗣昭立钟开元寺以七月十三日，弘农郡君夫人游硖石山则六月十四日。","考唐制有郡君夫人、公侯伯子夫人，制同一二三四品，似属嗣昭夫人杨氏。","但嗣昭封陇西郡公，未封弘农，或因弘农华阴以杨氏族望为称也。","又考杨氏善蓄财，嗣昭被梁兵围夹城弥年，杨氏多助其军用。","子继韬叛后入京，杨赍银数十万验赂释其罪。","后与子继忠家晋阳，余赀犹钜万。","晋高祖起义，贷其殖以赂契丹，后以继忠为刺史。","杨氏平生积产，嗣昭三世皆赖。","今复见其石刻笔迹，直奇妇人也。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-fab8ab69-3ff7-4cc9-85db-c2ffd98ea6e7","tags":[]},{"id":"poem-ca671cd1ed4e1fb5d4cb6e67","title":"兵要望江南 占梦第二十五（京本列第十三○九首） 二","author":"易静","dynasty":"唐","verses":["将军梦，云外见飞龙。","急去战时须获捷，不过三（辛本、川本作「百」）日帝王封，位显立奇功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-2e4ac0fd-bbcc-412e-976d-67e477aacb3f","tags":[]},{"id":"poem-ca6cd285b28cfc5053060702","title":"用诸公本韵各和一篇共三首  其二","author":"苏颂","dynasty":"宋","verses":["二纪书林得并迁，升沈俱喜在樽前。","非才幸复登群正，大笔犹稽直五砖。","欣听友声同伐木，坦忘情类似虚船。","白头光景尤须惜，乐事相逢且豁然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-63a6cd98-9dee-41e3-ab0f-190d1fa451c8","tags":[]},{"id":"poem-ca76c341291e3a401d5ed837","title":"秋寄李频使君二首 二","author":"贯休","dynasty":"唐","verses":["务简趣难陪，清吟共绿苔。","叶和秋蚁落，僧带野香来。","留客朝尝酒，忧民夜画灰。","终期冒风雪，江上见宗雷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-385e6970-ac1e-4aac-89a9-3d31c49b981a","tags":[]},{"id":"poem-ca780f751087e20a65924d22","title":"敬赠郑谏议十韵","author":"杜甫","dynasty":"唐","verses":["谏官非不达，诗义早知名。","破的由来事，先锋孰敢争。","思飘云物外，律中鬼神惊。","毫发无遗恨，波澜独老成。","野人宁得所，天意薄浮生。","多病休儒服，冥搜信客旌。","筑居仙缥缈，旅食岁峥嵘。","使者求颜阖，诸公厌祢衡。","将期一诺重，歘使寸心倾。","君见途穷哭，宜忧阮步兵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d4349582-0e9c-466c-8a27-da4663f34029","tags":[]},{"id":"poem-ca79c873be979018a0d7a2bf","title":"送朱屯田赴辟成都","author":"苏颂","dynasty":"宋","verses":["赞条初罢浙江回，辟命还从蜀道来。","朱绂聊光新幕府，乌星重照旧行台。","秋登危栈烟霄界，晓望通阛锦绣堆。","乐职定应能赋颂，知君堪继子渊才。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-590a828b-62c9-4d47-a34a-cafbdb81e20b","tags":[]},{"id":"poem-ca7e77cd1df1d9b407c4cc65","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦上)望孩儿终日倚门，怕儿夫语言不定。","哥哥嫂嫂忒薄幸，全不念手足情亲。","艰辛，十六年命屯，料今日枯枝再春。","(小生入相见，抱介)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8994","tags":[]},{"id":"poem-ca7eec030bbfdf85c9fadedc","title":"因僧看经颂","author":"文益","dynasty":"唐","verses":["今人看古教，不免心中闹。","欲免心中闹，但知看古教。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-9dd212ac-d2c4-40bd-ab7b-225c7634f220","tags":[]},{"id":"poem-ca810d229c136f54f26b6114","title":"咏史诗 姑苏台","author":"胡曾","dynasty":"唐","verses":["吴王恃霸弃雄才，贪向姑苏醉醁醅。","不觉钱塘江上月，一宵西送越兵来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9264904f-0f2b-4532-bcdd-b2ac5414168e","tags":["钱塘江"]},{"id":"poem-ca8921526978c5d45ff46f78","title":"生查子·散帙坐凝尘","author":"纳兰性德","dynasty":"清","verses":["散帙坐凝尘，吹气幽兰并。","茶名龙凤团，香字鸳鸯饼。","玉局类弹棋，颠倒双栖影。","花月不曾闲，莫放相思醒。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-25","tags":[]},{"id":"poem-ca89ed2bcda4eebddc54c372","title":"绕池游","author":"无名氏《张协状元》","dynasty":"元","verses":["张叶拜启：\"念是读书辈，往长安拟欲应举。","些少裹足，路途里欲得支费，望周全不须劫去。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2453","tags":[]},{"id":"poem-ca89f0b8aea4aa32f970ed8a","title":"自平","author":"杜甫","dynasty":"唐","verses":["自平宫中吕太一，收珠南海千余日。","近供生犀翡翠稀，复恐征戎干戈密。","蛮溪豪族小动摇，世封刺史非时朝。","蓬莱殿前诸主将，才如伏波不得骄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b207dcff-1823-4283-88d7-57d8c780c8ab","tags":[]},{"id":"poem-ca977eac8fd02a4462114903","title":"寒食宿陈公塘上","author":"徐铉","dynasty":"宋","verses":["垂杨界官道，茅屋倚高坡。","月下春塘水，风中牧竖歌。","折花闲立久，对酒远情多。","今夜孤亭梦，悠扬奈尔何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-cf27aa40-b08e-4ced-914e-fe86437d4cf6","tags":[]},{"id":"poem-caa13a85e8f31ef09fbdd5ba","title":"石室","author":"释了惠","dynasty":"宋","verses":["锤凿不到处，纵横丈许宽。","宁教苔藓去，要下一筹难。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-cc328623-8f77-475b-ad77-1925b97cbb49","tags":[]},{"id":"poem-cab8b1d0efbcba283984e9cd","title":"多景楼","author":"释居简","dynasty":"宋","verses":["好山可是登临少，此地云胡应接多。","天自有初恢壮观，人非无故辄悲歌。","烟收三面平开镜，雨后双鬟对绾螺。","欲辩南徐古徐话，忍将名刻细摩挲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-21a96680-beab-4235-9a53-c529653f2711","tags":[]}];
